INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0193', 'cable one arm straight back high row (kneeling)', 'back', 'back', 'cable', 'Attach a handle to a cable machine at waist height. Kneel down facing the cable machine and grab the handle with one hand. Keep your back straight and your core engaged. Pull the handle towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement. Slowly release the handle back to the starting position. Repeat for the desired number of repetitions. Switch sides and repeat the exercise with the other arm.', 'Sujeta una agarradera a una máquina de cable a la altura de la cintura. Ponte de rodillas frente a la máquina de cable y agarra la agarradera con una mano. Mantén la espalda recta y el core activado. Jala la agarradera hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el otro brazo.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/0193-WrYPP2g.jpg', 'videos/0193-WrYPP2g.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1723', 'cable one arm tricep pushdown', 'upper arms', 'upper arms', 'cable', 'Stand facing a cable machine with a straight bar attachment at chest height. Grasp the bar with an overhand grip and step back to create tension in the cable. Position your feet shoulder-width apart and slightly bend your knees. Keep your back straight and core engaged throughout the exercise. Start with your arm fully extended and perpendicular to the floor. Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended. Pause for a moment, then inhale and slowly return to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie frente a una máquina de cable con un accesorio de barra recta a la altura del pecho. Sujeta la barra con un agarre prono y retrocede un paso para crear tensión en el cable. Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas. Mantén la espalda recta y el core activado durante todo el ejercicio. Comienza con el brazo completamente extendido y perpendicular al suelo. Manteniendo la parte superior del brazo inmóvil, exhala y empuja la barra hacia abajo hasta que el brazo quede completamente extendido. Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'triceps', 'images/1723-qRZ5S1N.jpg', 'videos/1723-qRZ5S1N.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1636', 'cable overhead curl', 'upper arms', 'upper arms', 'cable', 'Attach a straight bar to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary. Exhale and curl the bar down towards your forehead, keeping your upper arms stationary. Pause for a moment at the bottom of the movement, squeezing your biceps. Inhale and slowly return the bar to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y curva la barra hacia la frente, manteniendo la parte superior de los brazos inmóvil. Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps. Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/1636-wDUqY2u.jpg', 'videos/1636-wDUqY2u.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1637', 'cable overhead curl on exercise ball', 'upper arms', 'upper arms', 'cable', 'Sit on an exercise ball and hold the cable handle with an underhand grip. Extend your arms fully overhead, keeping your elbows close to your ears. Slowly curl the cable down towards your forehead, keeping your upper arms stationary. Pause for a moment at the bottom of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de ejercicio y sujeta la agarradera del cable con un agarre supino. Extiende los brazos completamente por encima de la cabeza, manteniendo los codos cerca de las orejas. Curva lentamente el cable hacia la frente, manteniendo la parte superior de los brazos inmóvil. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/1637-ioTf098.jpg', 'videos/1637-ioTf098.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0194', 'cable overhead triceps extension (rope attachment)', 'upper arms', 'upper arms', 'cable', 'Attach a rope to a cable machine at a high position. Stand facing away from the machine with your feet shoulder-width apart. Grasp the rope with both hands, palms facing each other, and bring your hands above your head. Keep your upper arms close to your head and your elbows pointing forward. Slowly lower the rope behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una cuerda a una máquina de cable en una posición alta. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y lleva las manos por encima de la cabeza. Mantén la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante. Baja lentamente la cuerda detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0194-2IxROQ1.jpg', 'videos/0194-2IxROQ1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1319', 'cable palm rotational row', 'back', 'back', 'cable', 'Attach a handle to a cable machine at waist height. Stand facing the machine with your feet shoulder-width apart. Grasp the handle with an overhand grip, palms facing down. Step back to create tension on the cable, keeping your back straight and knees slightly bent. Pull the handle towards your body, rotating your palms to face upwards as you do so. Squeeze your shoulder blades together at the end of the movement. Slowly release the handle back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una agarradera a una máquina de cable a la altura de la cintura. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera con un agarre prono, con las palmas hacia abajo. Retrocede un paso para crear tensión en el cable, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Jala la agarradera hacia el cuerpo, rotando las palmas hacia arriba mientras lo haces. Aprieta los omóplatos al final del movimiento. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1319-OmQ8w0p.jpg', 'videos/1319-OmQ8w0p.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0195', 'cable preacher curl', 'upper arms', 'upper arms', 'cable', 'Adjust the cable machine so that the preacher curl pad is at chest height. Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip. Keep your back straight and your elbows tucked in at your sides. Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement. Pause for a moment, then slowly lower the cable attachment back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho. Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, agarrando el accesorio del cable con un agarre supino. Mantén la espalda recta y los codos pegados a los costados. Curva lentamente el accesorio del cable hacia los hombros, apretando los bíceps en la parte más alta del movimiento. Haz una pausa por un momento y luego baja lentamente el accesorio del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0195-P2lNrGL.jpg', 'videos/0195-P2lNrGL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1268', 'cable press on exercise ball', 'chest', 'chest', 'cable', 'Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle. Hold the cable handles at chest height with your palms facing down and your elbows bent. Engage your core and press the cable handles forward until your arms are fully extended. Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y las rodillas en un ángulo de 90 grados. Sujeta las agarraderas del cable a la altura del pecho con las palmas hacia abajo y los codos flexionados. Activa el core y empuja las agarraderas del cable hacia adelante hasta que los brazos queden completamente extendidos. Haz una pausa por un momento y luego libera lentamente la tensión, regresando las agarraderas del cable a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1268-vAwm6rK.jpg', 'videos/1268-vAwm6rK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0196', 'cable pull through (with rope)', 'upper legs', 'upper legs', 'cable', 'Stand facing away from the cable machine with your feet shoulder-width apart. Grab the rope attachment with both hands and step forward, creating tension in the cable. Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight. Engage your glutes and hamstrings to pull your body back up to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio de cuerda con ambas manos y da un paso hacia adelante, creando tensión en el cable. Flexiona las caderas y baja la parte superior del cuerpo hasta que quede paralela al suelo, manteniendo la espalda recta. Activa los glúteos y los isquiotibiales para llevar el cuerpo de vuelta hacia arriba, a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0196-OM46QHm.jpg', 'videos/0196-OM46QHm.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0198', 'cable pulldown', 'back', 'back', 'cable', 'Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured. Sit on the seat with your back straight and your feet flat on the ground. Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and engage your core. Pull the cable bar down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de jalón de cable de modo que el asiento quede a una altura cómoda y la almohadilla de rodillas esté asegurada. Siéntate con la espalda recta y los pies apoyados planos en el suelo. Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros. Inclínate ligeramente hacia atrás y activa el core. Jala la barra del cable hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0198-RVwzP10.jpg', 'videos/0198-RVwzP10.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0197', 'cable pulldown (pro lat bar)', 'back', 'back', 'cable', 'Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor. Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart. Sit down and lean back slightly, keeping your chest up and your back straight. Pull the bar down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento para que tus muslos queden paralelos al suelo y tus pies queden apoyados planos en el suelo. Sujeta la barra de jalón con un agarre prono, un poco más separado que el ancho de los hombros. Siéntate e inclínate ligeramente hacia atrás, manteniendo el pecho elevado y la espalda recta. Jala la barra hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0197-qdRxqCj.jpg', 'videos/0197-qdRxqCj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1638', 'cable pulldown bicep curl', 'upper arms', 'upper arms', 'cable', 'Attach a straight bar to the cable machine at the highest setting. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary. Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight. Pause for a moment at the bottom of the movement, squeezing your biceps. Inhale and slowly return the bar to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Sujeta una barra recta a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y curva lentamente la barra hacia los muslos, manteniendo las muñecas rectas. Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps. Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1638-QTXKWPh.jpg', 'videos/1638-QTXKWPh.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0201', 'cable pushdown', 'upper arms', 'upper arms', 'cable', 'Attach a straight bar to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees. Grasp the bar with an overhand grip, hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary. Exhale and push the bar down until your elbows are fully extended. Pause for a moment, then inhale and slowly return the bar to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y empuja la barra hacia abajo hasta que los codos queden completamente extendidos. Haz una pausa por un momento, luego inhala y regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'triceps', 'images/0201-3ZflifB.jpg', 'videos/0201-3ZflifB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0199', 'cable pushdown (straight arm) v. 2', 'back', 'back', 'cable', 'Attach a straight bar to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees. Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down. Engage your core and keep your back straight as you exhale and push the bar down towards your thighs. Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling. Repeat for the desired number of repetitions.', 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo. Activa el core y mantén la espalda recta mientras exhalas y empujas la barra hacia abajo en dirección a los muslos. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial mientras inhalas. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'lats', 'images/0199-PskORrA.jpg', 'videos/0199-PskORrA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0200', 'cable pushdown (with rope attachment)', 'upper arms', 'upper arms', 'cable', 'Attach a rope attachment to a high pulley on a cable machine. Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees. Grasp the rope with an overhand grip, palms facing each other. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Exhale and push the rope downward by extending your elbows until your arms are fully extended. Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex. Repeat for the desired number of repetitions.', 'Sujeta un accesorio de cuerda a una polea alta en una máquina de cable. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Exhala y empuja la cuerda hacia abajo extendiendo los codos hasta que los brazos queden completamente extendidos. Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial permitiendo que los codos se flexionen. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'triceps', 'images/0200-dU605di.jpg', 'videos/0200-dU605di.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0202', 'cable rear delt row (stirrups)', 'shoulders', 'shoulders', 'cable', 'Attach a stirrup handle to a low cable pulley and stand facing the machine. Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle. Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged. With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade. Pause for a moment at the top of the movement, squeezing your shoulder blade. Slowly release the handle back to the starting position and repeat for the desired number of repetitions. Switch sides and repeat the exercise with your right arm.', 'Sujeta un asa de estribo a una polea de cable baja y ponte de pie frente a la máquina. Sujeta el asa con la mano izquierda y retrocede un paso con el pie derecho, colocando el cuerpo en un ligero ángulo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Con el brazo izquierdo extendido y la palma hacia abajo, jala el asa hacia el pecho retrayendo el omóplato. Haz una pausa por un momento en la parte más alta del movimiento, apretando el omóplato. Suelta lentamente el asa de vuelta a la posición inicial y repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el brazo derecho.', 'trapezius', '["trapezius","rhomboids","biceps"]'::jsonb, 'delts', 'images/0202-yUdIGNs.jpg', 'videos/0202-yUdIGNs.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0203', 'cable rear delt row (with rope)', 'shoulders', 'shoulders', 'cable', 'Attach a rope handle to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the rope handle with an overhand grip, palms facing each other. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una agarradera de cuerda a una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera de cuerda con un agarre prono, con las palmas una frente a la otra. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Mantén los codos ligeramente flexionados y jala la cuerda hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte más alta del movimiento y luego libera lentamente la tensión, regresando a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids","biceps"]'::jsonb, 'delts', 'images/0203-wqNPGCg.jpg', 'videos/0203-wqNPGCg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0204', 'cable rear drive', 'upper arms', 'upper arms', 'cable', 'Attach a handle to a low pulley cable machine and stand facing away from the machine. Grasp the handle with an overhand grip and extend your arms straight out in front of you. Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement. Slowly return the handle to the starting position and repeat for the desired number of repetitions.', 'Sujeta una agarradera a una máquina de cable con polea baja y ponte de pie de espaldas a la máquina. Sujeta la agarradera con un agarre prono y extiende los brazos rectos frente a ti. Manteniendo los codos inmóviles, jala la agarradera de vuelta hacia el cuerpo, apretando los tríceps al final del movimiento. Regresa lentamente la agarradera a la posición inicial y repite el número de repeticiones deseado.', 'shoulders', '["shoulders","back"]'::jsonb, 'triceps', 'images/0204-c3QQLPi.jpg', 'videos/0204-c3QQLPi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0205', 'cable rear pulldown', 'back', 'back', 'cable', 'Adjust the cable machine so that the pulley is at the highest position. Sit facing the machine with your feet flat on the ground and your knees slightly bent. Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart. Lean back slightly, keeping your back straight and your chest up. Pull the cable attachment down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable de modo que la polea quede en la posición más alta. Siéntate frente a la máquina con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta el accesorio del cable con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado. Jala el accesorio del cable hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/0205-SpsOSXk.jpg', 'videos/0205-SpsOSXk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0873', 'cable reverse crunch', 'waist', 'waist', 'cable', 'Attach a cable to a low pulley and lie down facing up on a mat. Hold the cable with both hands and extend your arms straight up towards the ceiling. Bend your knees and lift your legs up, bringing your thighs towards your chest. While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Sujeta un cable a una polea baja y túmbate boca arriba sobre un tapete. Sujeta el cable con ambas manos y extiende los brazos rectos hacia el techo. Flexiona las rodillas y levanta las piernas, llevando los muslos hacia el pecho. Mientras mantienes la parte superior del cuerpo estable, curva la pelvis hacia el pecho, levantando las caderas del tapete. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0873-RqOtqD7.jpg', 'videos/0873-RqOtqD7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0206', 'cable reverse curl', 'upper arms', 'upper arms', 'cable', 'Attach a straight bar to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart and your knees slightly bent. Grasp the bar with an underhand grip, hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Exhale and curl the bar up towards your shoulders, contracting your biceps. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the bar back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Coloca una barra recta en una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0206-eOG0r6v.jpg', 'videos/0206-eOG0r6v.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2406', 'cable reverse grip triceps pushdown (sz-bar) (with arm blaster)', 'upper arms', 'upper arms', 'cable', 'Attach a straight bar to the cable machine at the highest setting. Stand facing the cable machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Engage your triceps and slowly push the bar down until your arms are fully extended. Pause for a moment at the bottom, then slowly return the bar to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una barra recta a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Activa los tríceps y empuja lentamente la barra hacia abajo hasta que los brazos queden completamente extendidos. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'triceps', 'images/2406-ThKP69G.jpg', 'videos/2406-ThKP69G.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1413', 'cable reverse one arm curl', 'upper arms', 'upper arms', 'cable', 'Stand facing a cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip, palm facing down. Keep your elbow close to your side and slowly curl your forearm up towards your shoulder. Pause for a moment at the top, then slowly lower your forearm back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino, con la palma hacia abajo. Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1413-gVlnLIJ.jpg', 'videos/1413-gVlnLIJ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0209', 'cable reverse preacher curl', 'upper arms', 'upper arms', 'cable', 'Adjust the cable machine so that the preacher curl pad is at chest height. Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended. Grab the cable handles with an underhand grip, shoulder-width apart. Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the handles back to the starting position, fully extending your elbows. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho. Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, con las palmas hacia abajo y los codos completamente extendidos. Agarra las agarraderas del cable con un agarre supino, separadas a la altura de los hombros. Manteniendo la parte superior de los brazos inmóvil, exhala y curva las agarraderas hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0209-IwX5NqK.jpg', 'videos/0209-IwX5NqK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0210', 'cable reverse wrist curl', 'lower arms', 'lower arms', 'cable', 'Attach a cable to a low pulley and sit on a bench facing the cable machine. Grasp the cable handle with an overhand grip, palms facing down. Rest your forearms on your thighs, with your wrists hanging off the edge. Keeping your forearms stationary, exhale and curl your wrists upward as far as possible. Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position. Repeat for the desired number of repetitions.', 'Sujeta un cable a una polea baja y siéntate en un banco frente a la máquina de cable. Sujeta la agarradera del cable con un agarre prono, con las palmas hacia abajo. Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Haz una pausa por un momento en la parte alta, luego inhala y baja lentamente las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms","wrists"]'::jsonb, 'forearms', 'images/0210-eYmsEPR.jpg', 'videos/0210-eYmsEPR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0207', 'cable reverse-grip pushdown', 'upper arms', 'upper arms', 'cable', 'Attach a straight bar to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted. Pause for a moment, then slowly return the bar to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Usando los tríceps, empuja la barra hacia abajo hasta que los brazos queden completamente extendidos y los tríceps contraídos. Haz una pausa por un momento y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'triceps', 'images/0207-VjYliFZ.jpg', 'videos/0207-VjYliFZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0208', 'cable reverse-grip straight back seated high row', 'back', 'back', 'cable', 'Sit on the seat facing the cable machine with your feet flat on the floor. Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart. Keep your back straight and lean slightly forward from your hips. Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles. Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Jala el cable hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda. Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0208-PNtsX17.jpg', 'videos/0208-PNtsX17.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1320', 'cable rope crossover seated row', 'back', 'back', 'cable', 'Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent. Grasp the cable ropes with an overhand grip, palms facing each other. Lean back slightly, keeping your back straight and your core engaged. Pull the cable ropes towards your chest, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado. Jala las cuerdas del cable hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1320-UFGF6gk.jpg', 'videos/1320-UFGF6gk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1321', 'cable rope elevated seated row', 'back', 'back', 'cable', 'Sit on the elevated seat facing the cable machine. Grab the cable rope handles with an overhand grip, palms facing each other. Keep your back straight and lean slightly back, maintaining a slight bend in your knees. Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles. Pause for a moment at the fully contracted position. Slowly release the tension and extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el asiento elevado frente a la máquina de cable. Agarra las agarraderas de cuerda con un agarre prono, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia atrás, conservando una ligera flexión en las rodillas. Jala el cable hacia el cuerpo retrayendo los omóplatos y apretando los músculos de la espalda. Haz una pausa por un momento en la posición de contracción completa. Libera lentamente la tensión y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1321-c8oybX6.jpg', 'videos/1321-c8oybX6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1322', 'cable rope extension incline bench row', 'back', 'back', 'cable', 'Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley. Attach a rope handle to the cable machine and sit on the incline bench facing the machine. Grab the rope handle with an overhand grip and lean forward, keeping your back straight. Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body. Squeeze your shoulder blades together at the end of the movement. Slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados y sujeta una máquina de cable a la polea baja. Sujeta una agarradera de cuerda a la máquina de cable y siéntate en el banco inclinado frente a la máquina. Agarra la agarradera de cuerda con un agarre prono e inclínate hacia adelante, manteniendo la espalda recta. Extiende los brazos por completo, jalando la cuerda hacia la parte superior del pecho mientras mantienes los codos cerca del cuerpo. Aprieta los omóplatos al final del movimiento. Libera lentamente la tensión y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/1322-MgKwAAo.jpg', 'videos/1322-MgKwAAo.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1639', 'cable rope hammer preacher curl', 'upper arms', 'upper arms', 'cable', 'Attach a rope attachment to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the rope with a neutral grip (palms facing each other). Position your upper arms against the preacher bench pad, keeping your elbows slightly bent. Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the rope back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta un accesorio de cuerda a una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra). Coloca la parte superior de los brazos contra la almohadilla del banco scott, manteniendo los codos ligeramente flexionados. Manteniendo la parte superior de los brazos inmóvil, exhala y curva la cuerda hacia los hombros contrayendo los bíceps. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la cuerda de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1639-PcPe0P5.jpg', 'videos/1639-PcPe0P5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1724', 'cable rope high pulley overhead tricep extension', 'upper arms', 'upper arms', 'cable', 'Attach a rope to a high pulley and adjust the weight accordingly. Stand facing away from the pulley machine with your feet shoulder-width apart. Grasp the rope with both hands, palms facing down, and bring your hands above your head. Keep your upper arms close to your head and perpendicular to the floor. Slowly lower the rope behind your head by bending your elbows. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una cuerda a una polea alta y ajusta el peso según corresponda. Ponte de pie de espaldas a la máquina de poleas con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos, con las palmas hacia abajo, y lleva las manos por encima de la cabeza. Mantén la parte superior de los brazos cerca de la cabeza y perpendicular al suelo. Baja lentamente la cuerda detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1724-NN8nSNT.jpg', 'videos/1724-NN8nSNT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1725', 'cable rope incline tricep extension', 'upper arms', 'upper arms', 'cable', 'Attach a rope to a high pulley and adjust the incline bench to a comfortable angle. Stand facing away from the pulley with your feet shoulder-width apart. Grasp the rope with an overhand grip and extend your arms straight overhead. Keep your elbows close to your head and your upper arms stationary throughout the exercise. Lower the rope behind your head by bending your elbows until your forearms touch your biceps. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una cuerda a una polea alta y ajusta el banco inclinado a un ángulo cómodo. Ponte de pie de espaldas a la polea con los pies separados a la altura de los hombros. Sujeta la cuerda con un agarre prono y extiende los brazos rectos por encima de la cabeza. Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio. Baja la cuerda detrás de la cabeza flexionando los codos hasta que los antebrazos toquen los bíceps. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1725-ZujAdR9.jpg', 'videos/1725-ZujAdR9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1726', 'cable rope lying on floor tricep extension', 'upper arms', 'upper arms', 'cable', 'Attach a rope to a cable machine and set it to the lowest position. Lie on the floor facing up, with your head towards the cable machine. Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling. Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una cuerda a una máquina de cable y colócala en la posición más baja. Túmbate en el suelo boca arriba, con la cabeza orientada hacia la máquina de cable. Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos hacia el techo. Mantén la parte superior de los brazos inmóvil y baja lentamente la cuerda hacia la frente, flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1726-U3ffHlY.jpg', 'videos/1726-U3ffHlY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1640', 'cable rope one arm hammer preacher curl', 'upper arms', 'upper arms', 'cable', 'Attach a rope handle to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the rope handle with an underhand grip, palms facing up. Position your upper arm against the preacher bench pad, keeping your elbow slightly bent. Keep your back straight and your core engaged throughout the exercise. Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary. Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Sujeta una agarradera de cuerda a una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera de cuerda con un agarre supino, con las palmas hacia arriba. Coloca la parte superior del brazo contra la almohadilla del banco scott, manteniendo el codo ligeramente flexionado. Mantén la espalda recta y el core activado durante todo el ejercicio. Curva lentamente la agarradera de cuerda hacia el hombro, manteniendo la parte superior del brazo inmóvil. Aprieta el bíceps en la parte más alta del movimiento y luego baja lentamente la agarradera de cuerda de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1640-4hATdoB.jpg', 'videos/1640-4hATdoB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1323', 'cable rope seated row', 'back', 'back', 'cable', 'Sit on the rowing machine with your feet flat on the footrests and knees slightly bent. Grasp the cable ropes with an overhand grip, palms facing each other. Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows. Pull the cable ropes towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos. Jala las cuerdas del cable hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1323-SJqRxOt.jpg', 'videos/1323-SJqRxOt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0211', 'cable russian twists (on stability ball)', 'waist', 'waist', 'cable', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold the cable handle with both hands and extend your arms straight out in front of you. Lean back slightly while keeping your back straight and your core engaged. Twist your torso to the right, bringing the cable handle towards your right hip. Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip. Continue alternating twists for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti. Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado. Gira el torso hacia la derecha, llevando la agarradera del cable hacia la cadera derecha. Haz una pausa por un momento y luego gira el torso hacia la izquierda, llevando la agarradera del cable hacia la cadera izquierda. Continúa alternando los giros el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0211-d9Xaxq6.jpg', 'videos/0211-d9Xaxq6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2144', 'cable seated chest press', 'chest', 'chest', 'cable', 'Adjust the seat height and cable handles to a comfortable position. Sit on the bench with your back straight and feet flat on the floor. Grasp the cable handles with an overhand grip at shoulder height. Push the handles forward and away from your body, extending your arms fully. Pause for a moment, then slowly bring the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y las agarraderas del cable a una posición cómoda. Siéntate en el banco con la espalda recta y los pies apoyados planos en el suelo. Sujeta las agarraderas del cable con un agarre prono a la altura del hombro. Empuja las agarraderas hacia adelante y alejándolas del cuerpo, extendiendo los brazos por completo. Haz una pausa por un momento y luego regresa lentamente las agarraderas a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/2144-nIR4Rwl.jpg', 'videos/2144-nIR4Rwl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0212', 'cable seated crunch', 'waist', 'waist', 'cable', 'Sit on a cable machine with your feet flat on the ground and your knees bent. Hold the cable handle with both hands and position it behind your head. Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees. Pause for a moment at the top, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas flexionadas. Sujeta la agarradera del cable con ambas manos y colócala detrás de la cabeza. Activa el abdomen y curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa por un momento en la parte alta y luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0212-8xUv4J7.jpg', 'videos/0212-8xUv4J7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1641', 'cable seated curl', 'upper arms', 'upper arms', 'cable', 'Sit on a cable machine with your feet flat on the ground and your back straight. Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended. Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Siéntate en una máquina de cable con los pies apoyados planos en el suelo y la espalda recta. Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo la parte superior de los brazos inmóvil, exhala y curva el accesorio del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1641-8oYqOt9.jpg', 'videos/1641-8oYqOt9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0213', 'cable seated high row (v-bar)', 'back', 'back', 'cable', 'Sit on the cable machine with your feet flat on the floor and your knees slightly bent. Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart. Keep your back straight and lean slightly forward from the hips. Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles. Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta el accesorio en V con un agarre prono, con las palmas una frente a la otra y las manos separadas a la altura de los hombros. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Jala el accesorio en V hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda. Haz una pausa por un momento en el punto más alto de la contracción, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/0213-pwt0pnM.jpg', 'videos/0213-pwt0pnM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0214', 'cable seated one arm alternate row', 'back', 'back', 'cable', 'Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent. Grasp the handle with one hand and keep your arm fully extended in front of you. Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side. Pause for a moment at the top of the movement, squeezing your back muscles. Slowly release the handle back to the starting position. Repeat with the other arm. Alternate between arms for the desired number of repetitions.', 'Siéntate en un banco frente a una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera con una mano y mantén el brazo completamente extendido frente a ti. Jala la agarradera hacia el cuerpo, retrayendo el omóplato y manteniendo el codo cerca del costado. Haz una pausa por un momento en la parte más alta del movimiento, apretando los músculos de la espalda. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0214-vpp9Ku2.jpg', 'videos/0214-vpp9Ku2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1642', 'cable seated one arm concentration curl', 'upper arms', 'upper arms', 'cable', 'Sit on a bench with your feet flat on the floor and your back straight. Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee. Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling. Pause for a moment at the top of the movement, squeezing your biceps. Slowly lower the cable handle back to the starting position while inhaling. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta. Sujeta una agarradera del cable con una mano y coloca el codo en la parte interna del muslo, justo arriba de la rodilla. Mantén la parte superior del brazo inmóvil y curva la agarradera del cable hacia el hombro mientras exhalas. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Baja lentamente la agarradera del cable de vuelta a la posición inicial mientras inhalas. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1642-rZ80Gbp.jpg', 'videos/1642-rZ80Gbp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1643', 'cable seated overhead curl', 'upper arms', 'upper arms', 'cable', 'Sit on a bench facing the cable machine with your feet flat on the ground. Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart. Keep your upper arms stationary and your elbows close to your sides. Exhale and curl the cable attachment towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén la parte superior de los brazos inmóvil y los codos cerca de los costados. Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/1643-DpWMFP5.jpg', 'videos/1643-DpWMFP5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0215', 'cable seated rear lateral raise', 'shoulders', 'shoulders', 'cable', 'Sit on a bench facing the cable machine with your feet flat on the ground. Grasp the cable handles with an overhand grip and extend your arms straight in front of you. Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta las agarraderas del cable con un agarre prono y extiende los brazos rectos frente a ti. Manteniendo los brazos rectos, levántalos lentamente hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","rhomboids"]'::jsonb, 'delts', 'images/0215-x825CZm.jpg', 'videos/0215-x825CZm.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0861', 'cable seated row', 'back', 'back', 'cable', 'Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent. Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed. Pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las agarraderas con un agarre prono, manteniendo la espalda recta y los hombros relajados. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0861-fUBheHs.jpg', 'videos/0861-fUBheHs.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0216', 'cable seated shoulder internal rotation', 'shoulders', 'shoulders', 'cable', 'Sit on a bench or chair facing the cable machine with your feet flat on the ground. Hold the cable handle with your arm extended straight out in front of you, parallel to the ground. Keep your elbow slightly bent and your shoulder blades pulled back and down. Slowly rotate your arm inward, bringing the cable handle towards the center of your body. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco o silla frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta la agarradera del cable con el brazo extendido recto frente a ti, paralelo al suelo. Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás y hacia abajo. Rota lentamente el brazo hacia adentro, llevando la agarradera del cable hacia el centro del cuerpo. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'rotator cuff', '["rotator cuff","triceps"]'::jsonb, 'delts', 'images/0216-YPoVrBi.jpg', 'videos/0216-YPoVrBi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2399', 'cable seated twist', 'waist', 'waist', 'cable', 'Sit on a cable machine with your feet flat on the ground and your knees slightly bent. Hold the cable handle with both hands and extend your arms straight in front of you. Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body. Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', 'Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti. Manteniendo el core activado, rota lentamente el torso hacia un lado, jalando el cable a través del cuerpo. Haz una pausa por un momento al final del rango de movimiento y luego rota lentamente de vuelta a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/2399-UEjSrKI.jpg', 'videos/2399-UEjSrKI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0218', 'cable seated wide-grip row', 'back', 'back', 'cable', 'Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent. Grasp the handle with a wide overhand grip, palms facing down. Keep your back straight and lean slightly forward from the hips. Pull the handle towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the peak of the contraction. Slowly release the handle back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Jala la agarradera hacia la parte baja del pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto de la contracción. Suelta lentamente la agarradera de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0218-qcY50ZD.jpg', 'videos/0218-qcY50ZD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0219', 'cable shoulder press', 'shoulders', 'shoulders', 'cable', 'Adjust the cable machine so that the handles are at shoulder height. Stand facing away from the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards. Press the handles upwards until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the handles back down to shoulder level. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable de modo que las agarraderas queden a la altura del hombro. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con un agarre prono y llévalas hasta la altura del hombro, con los codos flexionados y apuntando hacia afuera. Empuja las agarraderas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0219-PzQanLE.jpg', 'videos/0219-PzQanLE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0220', 'cable shrug', 'back', 'back', 'cable', 'Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable handles with an overhand grip and let your arms hang down in front of you. Keeping your arms straight, shrug your shoulders up towards your ears. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta las agarraderas del cable con un agarre prono y deja que los brazos cuelguen frente a ti. Manteniendo los brazos rectos, encoge los hombros hacia las orejas. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'traps', 'images/0220-Eg98Ft9.jpg', 'videos/0220-Eg98Ft9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0222', 'cable side bend', 'waist', 'waist', 'cable', 'Stand with your feet shoulder-width apart and grasp the cable handle with one hand. Keep your back straight and your core engaged. Slowly bend sideways at the waist, lowering the cable handle towards your knee. Pause for a moment, then return to the starting position. Repeat on the other side. Alternate sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con una mano. Mantén la espalda recta y el core activado. Flexiona lentamente la cintura hacia un lado, bajando la agarradera del cable hacia la rodilla. Haz una pausa breve y luego vuelve a la posición inicial. Repite del otro lado. Alterna los lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0222-wPypxFY.jpg', 'videos/0222-wPypxFY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0221', 'cable side bend crunch (bosu ball)', 'waist', 'waist', 'cable', 'Stand with your feet shoulder-width apart, holding a cable handle in one hand. Place the other hand on your hip. Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight. Pause for a moment at the bottom of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando la agarradera del cable con una mano. Coloca la otra mano en la cadera. Activa el core y flexiona lentamente la cintura hacia el lado en que sujetas el cable, manteniendo la espalda recta. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0221-qatbkEd.jpg', 'videos/0221-qatbkEd.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0223', 'cable side crunch', 'waist', 'waist', 'cable', 'Attach a cable handle to a low pulley and stand sideways to the machine. Grasp the handle with the hand furthest from the machine and place your other hand on your hip. Keep your feet shoulder-width apart and your knees slightly bent. With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Coloca un mango de cable en una polea baja y ponte de pie de lado a la máquina. Agarra el mango con la mano más alejada de la máquina y coloca la otra mano en tu cadera. Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas. Con el abdomen activado, flexiona la cintura hacia el lado, bajando el codo hacia la cadera. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0223-q2ADGqV.jpg', 'videos/0223-q2ADGqV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1717', 'cable squat row (with rope attachment)', 'back', 'back', 'cable', 'Attach a rope to a cable machine at waist height. Stand facing the cable machine with your feet shoulder-width apart. Bend your knees and lower your body into a squat position, keeping your back straight and chest up. Grasp the rope with an overhand grip, with your hands shoulder-width apart. Engage your core and pull the rope towards your body, squeezing your shoulder blades together. Keep your elbows close to your body and continue pulling until your hands reach your chest. Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una cuerda a una máquina de cable a la altura de la cintura. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Agarra la cuerda con un agarre prono, con las manos separadas a la altura de los hombros. Activa el core y tira de la cuerda hacia tu cuerpo, apretando los omóplatos entre sí. Mantén los codos cerca del cuerpo y continúa tirando hasta que las manos lleguen a tu pecho. Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente la cuerda y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/1717-f7fnAIB.jpg', 'videos/1717-f7fnAIB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1644', 'cable squatting curl', 'upper arms', 'upper arms', 'cable', 'Attach a cable handle to the lowest setting on a cable machine. Stand facing the machine with your feet shoulder-width apart. Hold the cable handle with an underhand grip, palms facing up, and arms fully extended. Lower your body into a squat position, keeping your back straight and knees behind your toes. As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides. Pause for a moment at the top of the curl, squeezing your biceps. Slowly lower the cable handle back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Coloca un mango de cable en el ajuste más bajo de una máquina de cable. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta el mango del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos. Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies. Mientras te agachas, flexiona el mango del cable hacia los hombros, manteniendo los codos cerca de los costados. Haz una pausa breve en la parte alta del movimiento, apretando los bíceps. Baja lentamente el mango del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1644-3XFdb1Z.jpg', 'videos/1644-3XFdb1Z.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0224', 'cable standing back wrist curl', 'lower arms', 'lower arms', 'cable', 'Stand facing a cable machine with your feet shoulder-width apart. Hold the cable handle with an overhand grip, palms facing down. Keep your arms straight and your elbows close to your sides. Slowly curl your wrists upward, bringing the cable handle towards your body. Pause for a moment at the top, then slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta el mango del cable con un agarre prono, con las palmas hacia abajo. Mantén los brazos rectos y los codos cerca de los costados. Flexiona lentamente las muñecas hacia arriba, llevando el mango del cable hacia tu cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/0224-VhX2JdE.jpg', 'videos/0224-VhX2JdE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1375', 'cable standing calf raise', 'lower legs', 'lower legs', 'cable', 'Stand facing a cable machine with your feet shoulder-width apart. Hold onto the cable machine handles or attach a cable ankle strap to your ankles. Raise your heels off the ground by extending your ankles as high as possible. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujétate de los mangos de la máquina de cable o coloca una correa de tobillo de cable en tus tobillos. Levanta los talones del suelo extendiendo los tobillos lo más alto posible. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1375-yl2IYyy.jpg', 'videos/1375-yl2IYyy.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0225', 'cable standing cross-over high reverse fly', 'shoulders', 'shoulders', 'cable', 'Attach a D-handle to each side of a cable machine at shoulder height. Stand in the middle of the cable machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward. Keep a slight bend in your elbows and maintain a straight back throughout the exercise. Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body. Pause for a moment at the peak of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Coloca un mango en D en cada lado de una máquina de cable a la altura de los hombros. Ponte de pie en el medio de la máquina de cable con los pies separados a la altura de los hombros. Agarra los mangos con un agarre prono y extiende los brazos hacia los lados, con las palmas hacia adelante. Mantén una ligera flexión en los codos y conserva la espalda recta durante todo el ejercicio. Activa los músculos de los hombros y aprieta los omóplatos entre sí mientras tiras de los mangos hacia la parte delantera de tu cuerpo. Haz una pausa breve en el punto máximo del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids","rear deltoids"]'::jsonb, 'delts', 'images/0225-P5p0j8B.jpg', 'videos/0225-P5p0j8B.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0226', 'cable standing crunch', 'waist', 'waist', 'cable', 'Attach a cable handle to a high pulley and stand facing away from the machine. Hold the handle with both hands and place it behind your head, keeping your elbows bent. Stand with your feet shoulder-width apart and your knees slightly bent. Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs. Pause for a moment at the bottom of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Coloca un mango de cable en una polea alta y ponte de pie de espaldas a la máquina. Sujeta el mango con ambas manos y colócalo detrás de la cabeza, manteniendo los codos flexionados. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Con el abdomen activado, exhala y flexiona el torso hacia las rodillas, llevando los codos hacia los muslos. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0226-jpgqxiS.jpg', 'videos/0226-jpgqxiS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0874', 'cable standing crunch (with rope attachment)', 'waist', 'waist', 'cable', 'Attach a rope to a cable machine at chest height. Stand facing away from the machine with your feet shoulder-width apart. Hold the rope with both hands and bring it behind your head, keeping your elbows bent. Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees. Pause for a moment at the top of the crunch, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una cuerda a una máquina de cable a la altura del pecho. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos y llévala detrás de la cabeza, manteniendo los codos flexionados. Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando los codos hacia las rodillas. Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0874-XU3ePuv.jpg', 'videos/0874-XU3ePuv.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0227', 'cable standing fly', 'chest', 'chest', 'cable', 'Attach the handles to the cables at chest height. Stand with your feet shoulder-width apart, facing away from the cable machine. Grasp the handles with an overhand grip, palms facing forward. Step forward slightly to create tension in the cables. Keep your core engaged and your back straight throughout the exercise. With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest. Squeeze your chest muscles at the peak of the movement. Slowly reverse the movement, returning your arms to the starting position. Repeat for the desired number of repetitions.', 'Coloca los mangos en los cables a la altura del pecho. Ponte de pie con los pies separados a la altura de los hombros, de espaldas a la máquina de cable. Agarra los mangos con un agarre prono, con las palmas hacia adelante. Da un paso adelante para crear tensión en los cables. Mantén el core activado y la espalda recta durante todo el ejercicio. Con una ligera flexión en los codos, lleva lentamente los brazos hacia adelante y júntalos frente al pecho. Aprieta los músculos del pecho en el punto máximo del movimiento. Invierte lentamente el movimiento, regresando los brazos a la posición inicial. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/0227-Pr9Rhf4.jpg', 'videos/0227-Pr9Rhf4.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0228', 'cable standing hip extension', 'upper legs', 'upper legs', 'cable', 'Attach a cable to a low pulley and stand facing away from the machine. Place the cable around your ankle and stand with your feet shoulder-width apart. Keep your core engaged and your back straight throughout the exercise. Slowly extend your leg straight back, squeezing your glutes at the top of the movement. Pause for a moment, then return to the starting position. Repeat for the desired number of repetitions. Switch sides and repeat with the other leg.', 'Sujeta un cable a una polea baja y ponte de pie de espaldas a la máquina. Coloca el cable alrededor de tu tobillo y ponte de pie con los pies separados a la altura de los hombros. Mantén el core activado y la espalda recta durante todo el ejercicio. Extiende lentamente la pierna hacia atrás, apretando los glúteos en la parte alta del movimiento. Haz una pausa breve y luego vuelve a la posición inicial. Repite el número de repeticiones deseado. Cambia de lado y repite con la otra pierna.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/0228-Kpajagk.jpg', 'videos/0228-Kpajagk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0229', 'cable standing inner curl', 'upper arms', 'upper arms', 'cable', 'Stand facing a cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip, palms facing up. Keep your elbows close to your sides and your upper arms stationary. Exhale and curl the cable handle towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Agarra el mango del cable con un agarre supino, con las palmas hacia arriba. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y flexiona el mango del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el mango del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0229-YwnI4ja.jpg', 'videos/0229-YwnI4ja.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0230', 'cable standing lift', 'waist', 'waist', 'cable', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with both hands and position it at waist height. Engage your core and maintain a straight back throughout the exercise. Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso. Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta el mango del cable con ambas manos y colócalo a la altura de la cintura. Activa el core y mantén la espalda recta durante todo el ejercicio. Manteniendo los brazos rectos, exhala y eleva el mango del cable hacia el hombro opuesto, rotando el torso. Haz una pausa breve en la parte alta, luego inhala y baja lentamente el mango del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0230-qFpAkpP.jpg', 'videos/0230-qFpAkpP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0231', 'cable standing one arm triceps extension', 'upper arms', 'upper arms', 'cable', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground. Keep your elbow stationary and close to your body. Slowly bend your elbow, lowering the cable handle towards the back of your head. Pause for a moment at the bottom of the movement, then extend your arm back to the starting position. Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm.', 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta el mango del cable con la mano derecha, con la palma hacia abajo, y coloca el brazo completamente extendido y paralelo al suelo. Mantén el codo quieto y cerca del cuerpo. Flexiona lentamente el codo, bajando el mango del cable hacia la parte de atrás de la cabeza. Haz una pausa breve en la parte baja del movimiento, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0231-sYCcnon.jpg', 'videos/0231-sYCcnon.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1376', 'cable standing one leg calf raise', 'lower legs', 'lower legs', 'cable', 'Stand facing a cable machine with your feet shoulder-width apart. Hold onto the cable machine for support. Lift one leg off the ground and balance on the other leg. Slowly raise your heel off the ground, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujétate de la máquina de cable para apoyarte. Levanta una pierna del suelo y equilíbrate sobre la otra pierna. Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'ankles', '["ankles","feet"]'::jsonb, 'calves', 'images/1376-fgc9Xdl.jpg', 'videos/1376-fgc9Xdl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0232', 'cable standing pulldown (with rope)', 'upper arms', 'upper arms', 'cable', 'Attach a rope to the cable machine at the highest setting. Stand facing the machine with your feet shoulder-width apart. Grasp the rope with an overhand grip, palms facing down. Keep your back straight and core engaged throughout the exercise. Pull the rope down towards your thighs, squeezing your biceps. Pause for a moment at the bottom, then slowly release the rope back up. Repeat for the desired number of repetitions.', 'Sujeta una cuerda a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Agarra la cuerda con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira de la cuerda hacia abajo, hacia los muslos, apretando los bíceps. Haz una pausa breve en la parte baja, luego suelta lentamente la cuerda hacia arriba. Repite el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/0232-CvPn9WV.jpg', 'videos/0232-CvPn9WV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0233', 'cable standing rear delt row (with rope)', 'shoulders', 'shoulders', 'cable', 'Stand facing a cable machine with your feet shoulder-width apart. Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable. Keep your back straight and your core engaged. Pull the cable towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta el accesorio del cable con ambas manos, con las palmas una frente a la otra, y retrocede un paso para crear tensión en el cable. Mantén la espalda recta y el core activado. Tira del cable hacia tu cuerpo, apretando los omóplatos entre sí. Haz una pausa breve en el punto máximo del movimiento, luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids","biceps"]'::jsonb, 'delts', 'images/0233-ZfyAGhK.jpg', 'videos/0233-ZfyAGhK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1727', 'cable standing reverse grip one arm overhead tricep extension', 'upper arms', 'upper arms', 'cable', 'Stand facing away from the cable machine with your feet shoulder-width apart. Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head. Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow. Pause for a moment at the bottom, then extend your arm back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros. Sujeta el mango del cable con un agarre supino y extiende el brazo por encima de la cabeza, manteniendo el codo cerca de la cabeza. Mantén el brazo superior quieto y baja lentamente el mango del cable detrás de la cabeza flexionando el codo. Haz una pausa breve en la parte baja, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1727-i11JWU7.jpg', 'videos/1727-i11JWU7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0234', 'cable standing row (v-bar)', 'back', 'back', 'cable', 'Stand facing the cable machine with your feet shoulder-width apart. Grasp the v-bar attachment with an overhand grip, palms facing down. Keep your back straight and your core engaged. Pull the v-bar towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta y el core activado. Tira del accesorio en V hacia tu cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/0234-4f8RXP8.jpg', 'videos/0234-4f8RXP8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0235', 'cable standing shoulder external rotation', 'shoulders', 'shoulders', 'cable', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the cable handle with your arm extended in front of you, parallel to the ground. Keep your elbow slightly bent and your shoulder blades pulled back. Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta el mango del cable con el brazo extendido frente a ti, paralelo al suelo. Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás. Rota lentamente el brazo hacia afuera, alejándolo de tu cuerpo, manteniendo el codo en la misma posición. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'rotator cuff', '["rotator cuff","trapezius"]'::jsonb, 'delts', 'images/0235-FWdVhcW.jpg', 'videos/0235-FWdVhcW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0236', 'cable standing twist row (v-bar)', 'back', 'back', 'cable', 'Attach a v-bar attachment to a cable machine at chest height. Stand facing the cable machine with your feet shoulder-width apart. Grasp the v-bar with an overhand grip, palms facing down. Take a step back to create tension in the cable. Keep your back straight and core engaged throughout the exercise. Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows. As you pull, twist your torso to one side, squeezing your shoulder blades together. Pause for a moment at the top of the movement, feeling the contraction in your upper back. Slowly release the tension and return to the starting position, untwisting your torso. Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep.', 'Coloca un accesorio en V en una máquina de cable a la altura del pecho. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo. Da un paso atrás para crear tensión en el cable. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira del accesorio en V hacia tu torso retrayendo los omóplatos y flexionando los codos. Mientras tiras, gira el torso hacia un lado, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta del movimiento, sintiendo la contracción en la parte alta de la espalda. Suelta lentamente la tensión y regresa a la posición inicial, deshaciendo el giro del torso. Repite el movimiento el número de repeticiones deseado, alternando la dirección del giro en cada repetición.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/0236-JOZhu2h.jpg', 'videos/0236-JOZhu2h.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1269', 'cable standing up straight crossovers', 'chest', 'chest', 'cable', 'Stand in the middle of a cable machine with your feet shoulder-width apart. Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides. Keeping your arms straight, bring your hands together in front of your body, crossing them over each other. Pause for a moment, then slowly return to the starting position, keeping your arms extended. Repeat for the desired number of repetitions.', 'Ponte de pie en el medio de una máquina de cable con los pies separados a la altura de los hombros. Sujeta los mangos de los cables con las palmas hacia abajo y los brazos extendidos hacia los lados. Manteniendo los brazos rectos, junta las manos frente a tu cuerpo, cruzándolas una sobre la otra. Haz una pausa breve, luego regresa lentamente a la posición inicial, manteniendo los brazos extendidos. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/1269-UKWTJWR.jpg', 'videos/1269-UKWTJWR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0238', 'cable straight arm pulldown', 'back', 'back', 'cable', 'Attach a straight bar to the high pulley of a cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down. Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement. Pause for a moment at the bottom, then slowly return the bar to the starting position. Repeat for the desired number of repetitions.', 'Coloca una barra recta en la polea alta de una máquina de cable. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo. Activa los dorsales y tira de la barra hacia abajo, hacia los muslos, manteniendo los brazos rectos durante todo el movimiento. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","biceps"]'::jsonb, 'lats', 'images/0238-x69MAlq.jpg', 'videos/0238-x69MAlq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0237', 'cable straight arm pulldown (with rope)', 'back', 'back', 'cable', 'Attach a rope to the cable machine at the highest setting. Stand facing the machine with your feet shoulder-width apart. Grasp the rope with both hands, palms facing down. Extend your arms fully in front of you, keeping your elbows slightly bent. Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight. Pause for a moment at the bottom, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una cuerda a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Agarra la cuerda con ambas manos, con las palmas hacia abajo. Extiende completamente los brazos frente a ti, manteniendo los codos ligeramente flexionados. Activa los dorsales y tira lentamente de la cuerda hacia abajo, hacia los muslos, manteniendo los brazos rectos. Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0237-DT14T9T.jpg', 'videos/0237-DT14T9T.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0239', 'cable straight back seated row', 'back', 'back', 'cable', 'Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent. Grasp the cable handles with an overhand grip, palms facing down. Keep your back straight and lean slightly forward from the hips. Pull the cable handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Agarra los mangos del cable con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Tira de los mangos del cable hacia tu cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms","shoulders"]'::jsonb, 'upper back', 'images/0239-Tq6gbK6.jpg', 'videos/0239-Tq6gbK6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0240', 'cable supine reverse fly', 'shoulders', 'shoulders', 'cable', 'Attach a D-handle to a low pulley cable machine and lie face down on a flat bench. Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you. Keeping your arms straight, raise them out to the sides until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Coloca un mango en D en una máquina de cable con polea baja y túmbate boca abajo en un banco plano. Agarra el mango en D con cada mano, con las palmas hacia abajo, y extiende los brazos frente a ti. Manteniendo los brazos rectos, levántalos hacia los lados hasta que estén paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/0240-PQcUlDi.jpg', 'videos/0240-PQcUlDi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2464', 'cable thibaudeau kayak row', 'back', 'back', 'cable', 'Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor. Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow. Lean forward from your hips, keeping your back straight and your abs engaged. Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body. Squeeze your back muscles at the top of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides and perform with your left arm.', 'Coloca un mango de cable en una polea baja y siéntate frente a la máquina con los pies planos en el suelo. Agarra el mango con la mano derecha y extiende completamente el brazo, manteniendo una ligera flexión en el codo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el abdomen activado. Tira del mango hacia tu torso retrayendo el omóplato y flexionando el codo, manteniendo el brazo cerca del cuerpo. Aprieta los músculos de la espalda en la parte alta del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/2464-ZgwWBoC.jpg', 'videos/2464-ZgwWBoC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0241', 'cable triceps pushdown (v-bar)', 'upper arms', 'upper arms', 'cable', 'Attach a v-bar attachment to the cable machine at the highest setting. Stand facing the cable machine with your feet shoulder-width apart. Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Engage your triceps and exhale as you push the v-bar down until your arms are fully extended. Pause for a moment at the bottom of the movement, squeezing your triceps. Inhale as you slowly return the v-bar to the starting position, maintaining control. Repeat for the desired number of repetitions.', 'Coloca un accesorio en V en la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte baja del movimiento, apretando los tríceps. Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'triceps', 'images/0241-gAwDzB3.jpg', 'videos/0241-gAwDzB3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2405', 'cable triceps pushdown (v-bar) (with arm blaster)', 'upper arms', 'upper arms', 'cable', 'Attach a v-bar attachment to the cable machine at the highest setting. Stand facing the cable machine with your feet shoulder-width apart. Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Engage your triceps and exhale as you push the v-bar down until your arms are fully extended. Pause for a moment at the bottom of the movement, squeezing your triceps. Inhale as you slowly return the v-bar to the starting position, maintaining control. Repeat for the desired number of repetitions.', 'Coloca un accesorio en V en la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte baja del movimiento, apretando los tríceps. Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'triceps', 'images/2405-OxJk1fg.jpg', 'videos/2405-OxJk1fg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0242', 'cable tuck reverse crunch', 'waist', 'waist', 'cable', 'Attach a cable to a low pulley and lie down on a mat facing up. Hold the cable with both hands and extend your arms straight up above your chest. Bend your knees and lift your legs up, bringing your knees towards your chest. At the same time, curl your pelvis up towards your chest, lifting your hips off the ground. Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position. Repeat for the desired number of repetitions.', 'Sujeta un cable a una polea baja y túmbate boca arriba sobre una esterilla. Sujeta el cable con ambas manos y extiende los brazos rectos por encima del pecho. Flexiona las rodillas y levanta las piernas, llevando las rodillas hacia el pecho. Al mismo tiempo, eleva la pelvis hacia el pecho, levantando las caderas del suelo. Haz una pausa breve en la parte alta, luego baja lentamente las piernas y las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0242-TXtXc84.jpg', 'videos/0242-TXtXc84.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0243', 'cable twist', 'waist', 'waist', 'cable', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent. Engage your core and twist your torso to the right, pulling the cable across your body. Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques. Slowly return to the starting position, resisting the cable''s pull. Repeat the movement to the left side. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados. Activa el core y gira el torso hacia la derecha, tirando del cable a través de tu cuerpo. Haz una pausa breve al final del movimiento, sintiendo la contracción en el abdomen y los oblicuos. Regresa lentamente a la posición inicial, resistiendo la tracción del cable. Repite el movimiento hacia el lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0243-aVs3BR3.jpg', 'videos/0243-aVs3BR3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0862', 'cable twist (up-down)', 'waist', 'waist', 'cable', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent. Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable. Pause for a moment at the end of the rotation, then slowly return to the starting position. Repeat the rotation to the opposite side. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados. Activa el core y gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el giro hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0862-fhZQPlV.jpg', 'videos/0862-fhZQPlV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0244', 'cable twisting pull', 'back', 'back', 'cable', 'Attach a cable handle to a low pulley and stand facing the machine. Grasp the handle with your left hand and step away from the machine, extending your arm fully. Position your feet shoulder-width apart, with your knees slightly bent. Keep your back straight and your core engaged throughout the exercise. Pull the handle towards your body, rotating your torso to the right as you do so. Squeeze your back muscles at the end of the movement. Slowly return to the starting position, keeping tension on the cable. Repeat for the desired number of repetitions, then switch sides and perform with your right hand.', 'Coloca un mango de cable en una polea baja y ponte de pie frente a la máquina. Agarra el mango con la mano izquierda y aléjate de la máquina, extendiendo completamente el brazo. Coloca los pies separados a la altura de los hombros, con las rodillas ligeramente flexionadas. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira del mango hacia tu cuerpo, rotando el torso hacia la derecha al hacerlo. Aprieta los músculos de la espalda al final del movimiento. Regresa lentamente a la posición inicial, manteniendo la tensión en el cable. Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con la mano derecha.', 'shoulders', '["shoulders","biceps"]'::jsonb, 'lats', 'images/0244-zCgxPbV.jpg', 'videos/0244-zCgxPbV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1645', 'cable two arm curl on incline bench', 'upper arms', 'upper arms', 'cable', 'Sit on an incline bench with your back against the pad and your feet flat on the ground. Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended. Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the handles back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo. Agarra los mangos del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona los mangos hacia los hombros mientras contraes los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1645-H9y3Dkr.jpg', 'videos/1645-H9y3Dkr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1728', 'cable two arm tricep kickback', 'upper arms', 'upper arms', 'cable', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle. Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta el mango del cable en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados. Manteniendo los brazos superiores quietos, extiende los antebrazos hacia atrás hasta que los brazos estén completamente extendidos. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1728-vvNjDJS.jpg', 'videos/1728-vvNjDJS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0245', 'cable underhand pulldown', 'back', 'back', 'cable', 'Adjust the cable machine so that the pulldown bar is at a height above your head. Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and lean back slightly. Pull the bar down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza. Siéntate y agarra la barra de jalón con un agarre supino, con las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta e inclínate ligeramente hacia atrás. Jala la barra hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0245-xBYcQHj.jpg', 'videos/0245-xBYcQHj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1270', 'cable upper chest crossovers', 'chest', 'chest', 'cable', 'Attach the handles to the cables at chest height. Stand in the center of the cable machine with one foot slightly in front of the other. Grasp the handles with your palms facing down and your arms extended out to the sides. Keep a slight bend in your elbows and engage your core. Pull the cables together in front of your chest, crossing them over each other. Squeeze your chest muscles at the peak of the movement. Slowly release the cables back to the starting position. Repeat for the desired number of repetitions.', 'Coloca los mangos en los cables a la altura del pecho. Ponte de pie en el centro de la máquina de cable con un pie ligeramente delante del otro. Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados. Mantén una ligera flexión en los codos y activa el core. Tira de los cables juntos frente al pecho, cruzándolos uno sobre el otro. Aprieta los músculos del pecho en el punto máximo del movimiento. Suelta lentamente los cables de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/1270-j7XMAyn.jpg', 'videos/1270-j7XMAyn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1324', 'cable upper row', 'back', 'back', 'cable', 'Attach a straight bar to a cable machine at chest height. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and your core engaged. Pull the bar towards your upper chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement. Slowly release the bar back to the starting position. Repeat for the desired number of repetitions.', 'Sujeta una barra recta a una máquina de cable a la altura del pecho. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el core activado. Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/1324-PQStVXH.jpg', 'videos/1324-PQStVXH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0246', 'cable upright row', 'shoulders', 'shoulders', 'cable', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip. Keep your back straight and your core engaged throughout the exercise. Pull the cable attachment straight up towards your chin, leading with your elbows. Pause for a moment at the top, squeezing your shoulder blades together. Slowly lower the cable attachment back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta el accesorio del cable con un agarre prono. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira del accesorio del cable directamente hacia arriba, hacia tu barbilla, guiando con los codos. Haz una pausa breve en la parte alta, apretando los omóplatos entre sí. Baja lentamente el accesorio del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","biceps"]'::jsonb, 'delts', 'images/0246-cALKspW.jpg', 'videos/0246-cALKspW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1325', 'cable wide grip rear pulldown behind neck', 'back', 'back', 'cable', 'Adjust the cable machine so that the pulldown bar is at a height above your head. Sit down on the seat and grab the pulldown bar with a wide overhand grip. Keep your back straight and your chest up as you lean back slightly. Pull the bar down towards your upper chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza. Siéntate y agarra la barra de jalón con un agarre prono amplio. Mantén la espalda recta y el pecho elevado mientras te reclinas ligeramente hacia atrás. Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/1325-CmEr4pM.jpg', 'videos/1325-CmEr4pM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0247', 'cable wrist curl', 'lower arms', 'lower arms', 'cable', 'Attach a straight bar to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart. Rest your forearms on a bench or pad, with your wrists hanging off the edge. Keeping your forearms stationary, exhale and curl your wrists upward as far as possible. Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position. Repeat for the desired number of repetitions.', 'Coloca una barra recta en una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Apoya los antebrazos en un banco o almohadilla, con las muñecas colgando del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Haz una pausa breve en la parte alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/0247-LrV4s90.jpg', 'videos/0247-LrV4s90.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1407', 'calf push stretch with hands against wall', 'lower legs', 'lower legs', 'body weight', 'Stand facing a wall with your feet hip-width apart. Place your hands against the wall at shoulder height. Step back with one foot, keeping your heel on the ground and your leg straight. Bend your front knee slightly and lean forward, feeling a stretch in your calf. Hold the stretch for 20-30 seconds. Switch legs and repeat the stretch.', 'Ponte de pie frente a una pared con los pies separados a la altura de las caderas. Coloca las manos contra la pared a la altura de los hombros. Da un paso atrás con un pie, manteniendo el talón en el suelo y la pierna recta. Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, sintiendo un estiramiento en la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/1407-PzNxakt.jpg', 'videos/1407-PzNxakt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1377', 'calf stretch with hands against wall', 'lower legs', 'lower legs', 'body weight', 'Stand facing a wall with your feet hip-width apart. Place your hands against the wall at shoulder height. Step your right foot back, keeping your heel on the ground and your leg straight. Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground. Hold the stretch for 20-30 seconds. Switch legs and repeat the stretch.', 'Ponte de pie frente a una pared con los pies separados a la altura de las caderas. Coloca las manos contra la pared a la altura de los hombros. Da un paso atrás con el pie derecho, manteniendo el talón en el suelo y la pierna recta. Flexiona la rodilla izquierda e inclínate hacia adelante, manteniendo la pierna de atrás recta y el talón en el suelo. Mantén el estiramiento durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/1377-m0tCHqc.jpg', 'videos/1377-m0tCHqc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1378', 'calf stretch with rope', 'lower legs', 'lower legs', 'rope', 'Stand facing a wall or sturdy object with your feet hip-width apart. Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot. Step back with your left foot, keeping your heel on the ground and your leg straight. Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf. Hold the stretch for 20-30 seconds, then release. Repeat on the other leg.', 'Ponte de pie frente a una pared u objeto firme con los pies separados a la altura de las caderas. Sujeta los extremos de la cuerda con cada mano y coloca el centro de la cuerda alrededor de la planta del pie derecho. Da un paso atrás con el pie izquierdo, manteniendo el talón en el suelo y la pierna recta. Inclínate hacia adelante, manteniendo la espalda recta, y tira suavemente de la cuerda para estirar la pantorrilla. Mantén el estiramiento durante 20-30 segundos, luego suelta. Repite con la otra pierna.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/1378-1LVFcEn.jpg', 'videos/1378-1LVFcEn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0248', 'cambered bar lying row', 'back', 'back', 'barbell', 'Set up a barbell on the floor and lie face down on a bench with your chest just off the edge. Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart. With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms. Pull the barbell towards your chest, squeezing your shoulder blades together. Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', 'Coloca una barra en el suelo y túmbate boca abajo en un banco con el pecho justo en el borde. Estírate hacia abajo y agarra la barra con un agarre prono, un poco más ancho que el ancho de los hombros. Con las piernas rectas y los pies en el suelo, levanta la barra del suelo extendiendo los brazos. Tira de la barra hacia el pecho, juntando los omóplatos. Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0248-R5swFnc.jpg', 'videos/0248-R5swFnc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2963', 'captains chair straight leg raise', 'waist', 'waist', 'body weight', 'Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads. Keep your upper body stable and your back straight. Engage your abs and lift your legs up in front of you, keeping them straight. Continue lifting until your legs are parallel to the ground or as high as you can comfortably go. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en la silla romana con la espalda apoyada en el respaldo y los antebrazos apoyados en las almohadillas. Mantén la parte superior del cuerpo estable y la espalda recta. Activa el abdomen y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/2963-weoDEpH.jpg', 'videos/2963-weoDEpH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1548', 'chair leg extended stretch', 'upper legs', 'upper legs', 'body weight', 'Sit on the edge of a chair with your back straight and feet flat on the ground. Extend one leg straight out in front of you, keeping your heel on the ground. Lean forward slightly, feeling a stretch in your quadriceps. Hold this position for 20-30 seconds. Switch legs and repeat the stretch.', 'Siéntate al borde de una silla con la espalda recta y los pies planos en el suelo. Extiende una pierna recta frente a ti, manteniendo el talón en el suelo. Inclínate ligeramente hacia adelante, sintiendo un estiramiento en los cuádriceps. Mantén esta posición durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', 'hamstrings', '["hamstrings","calves"]'::jsonb, 'quads', 'images/1548-xGgAGPm.jpg', 'videos/1548-xGgAGPm.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1271', 'chest and front of shoulder stretch', 'chest', 'chest', 'body weight', 'Stand tall with your feet shoulder-width apart. Extend your arms straight out in front of you at shoulder height. Cross your arms in front of your body, with your right arm on top of your left arm. Interlace your fingers and press your palms together. Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders. Hold the stretch for 20-30 seconds, then release. Repeat for the desired number of repetitions.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende los brazos rectos frente a ti a la altura de los hombros. Cruza los brazos frente a tu cuerpo, con el brazo derecho sobre el brazo izquierdo. Entrelaza los dedos y presiona las palmas entre sí. Aprieta suavemente los omóplatos entre sí y empuja las manos hacia adelante, sintiendo un estiramiento en el pecho y la parte delantera de los hombros. Mantén el estiramiento durante 20-30 segundos, luego suelta. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids"]'::jsonb, 'pectorals', 'images/1271-Uto7l43.jpg', 'videos/1271-Uto7l43.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0251', 'chest dip', 'chest', 'chest', 'body weight', 'Position yourself on parallel bars with your arms fully extended and your body straight. Lower your body by bending your elbows until your shoulders are below your elbows. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Colócate en las barras paralelas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0251-9WTm7dq.jpg', 'videos/0251-9WTm7dq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1430', 'chest dip (on dip-pull-up cage)', 'chest', 'chest', 'body weight', 'Adjust the dip bars to a height that allows you to comfortably grip them. Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart. Jump up and straighten your arms, supporting your body weight on the bars. Bend your knees and cross your ankles behind you. Lower your body by bending your elbows, keeping your chest up and your shoulders down. Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest. Push through your palms and extend your elbows to raise your body back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta las barras de fondos a una altura que te permita agarrarlas cómodamente. Ponte de pie entre las barras y coloca las manos en cada barra, un poco más separadas que el ancho de los hombros. Salta y estira los brazos, sosteniendo el peso de tu cuerpo sobre las barras. Flexiona las rodillas y cruza los tobillos detrás de ti. Baja el cuerpo flexionando los codos, manteniendo el pecho elevado y los hombros bajos. Continúa bajando hasta que los hombros queden por debajo de los codos o hasta que sientas un estiramiento en el pecho. Empuja con las palmas y extiende los codos para subir el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1430-XgWyAiA.jpg', 'videos/1430-XgWyAiA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2462', 'chest dip on straight bar', 'chest', 'chest', 'body weight', 'Grab the parallel bars with your palms facing down and your arms fully extended. Bend your knees and cross your ankles. Lower your body by bending your arms until your shoulders are below your elbows. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Agarra las barras paralelas con las palmas hacia abajo y los brazos completamente extendidos. Flexiona las rodillas y cruza los tobillos. Baja el cuerpo flexionando los brazos hasta que los hombros queden por debajo de los codos. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/2462-LQFOrMn.jpg', 'videos/2462-LQFOrMn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1272', 'chest stretch with exercise ball', 'chest', 'chest', 'stability ball', 'Sit on the stability ball with your feet flat on the ground and your back straight. Hold the exercise ball with both hands and extend your arms straight out in front of you. Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles. Hold the stretch for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta. Sujeta el balón de ejercicio con ambas manos y extiende los brazos rectos frente a ti. Lleva lentamente el balón de ejercicio hacia tu pecho, sintiendo un estiramiento en los músculos del pecho. Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1272-ykA5tU7.jpg', 'videos/1272-ykA5tU7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3216', 'chest tap push-up (male)', 'chest', 'chest', 'body weight', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line. Lower your body towards the ground by bending your elbows, keeping them close to your sides. As you lower yourself, tap your chest with your right hand. Push yourself back up to the starting position. Repeat the movement, this time tapping your chest with your left hand. Continue alternating sides for the desired number of repetitions.', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Mientras te bajas, toca tu pecho con la mano derecha. Empújate de vuelta hacia arriba hasta la posición inicial. Repite el movimiento, esta vez tocando tu pecho con la mano izquierda. Continúa alternando lados durante el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/3216-7E06s6d.jpg', 'videos/3216-7E06s6d.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1326', 'chin-up', 'back', 'back', 'body weight', 'Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart. Engage your core and pull your body up towards the bar, leading with your chest. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/1326-T2mxWqc.jpg', 'videos/1326-T2mxWqc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0253', 'chin-ups (narrow parallel grip)', 'back', 'back', 'body weight', 'Hang from a pull-up bar with a narrow parallel grip, palms facing towards you. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con un agarre paralelo estrecho, con las palmas hacia ti. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0253-G70mEAJ.jpg', 'videos/0253-G70mEAJ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0257', 'circles knee stretch', 'lower legs', 'lower legs', 'body weight', 'Stand with your feet shoulder-width apart and your hands on your hips. Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet. Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise. Perform the movement for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas. Flexiona ligeramente las rodillas y levanta los talones del suelo, equilibrándote sobre las puntas de los pies. Manteniendo las rodillas flexionadas, gira las rodillas en un movimiento circular, primero en el sentido de las agujas del reloj y luego en sentido contrario. Realiza el movimiento el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'calves', 'images/0257-X7jbxra.jpg', 'videos/0257-X7jbxra.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1273', 'clap push up', 'chest', 'chest', 'body weight', 'Start in a high plank position with your hands slightly wider than shoulder-width apart. Lower your body towards the ground by bending your elbows, keeping your core engaged. Push through your palms explosively to propel your body off the ground. While in mid-air, clap your hands together before landing back in the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado. Empuja con las palmas de forma explosiva para impulsar tu cuerpo fuera del suelo. Mientras estás en el aire, junta las manos en un aplauso antes de aterrizar de vuelta en la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1273-wigSg76.jpg', 'videos/1273-wigSg76.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0258', 'clock push-up', 'chest', 'chest', 'body weight', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Lower your body towards the ground by bending your elbows, keeping them close to your sides. As you lower, rotate your body to the left, extending your left arm straight out to the side. Push back up to the starting position, while rotating your body to the center. Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side. Continue alternating sides with each repetition.', 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Mientras bajas, gira el cuerpo hacia la izquierda, extendiendo el brazo izquierdo recto hacia el lado. Empuja de vuelta hacia arriba hasta la posición inicial, mientras giras el cuerpo hacia el centro. Repite la flexión de brazos, esta vez girando el cuerpo hacia la derecha y extendiendo el brazo derecho hacia el lado. Continúa alternando lados en cada repetición.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/0258-CMAxnsG.jpg', 'videos/0258-CMAxnsG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1327', 'close grip chin-up', 'back', 'back', 'body weight', 'Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart. Hang from the bar with your arms fully extended and your feet off the ground. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Agarra la barra de dominadas con las palmas hacia ti y las manos separadas a la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/1327-VnfUNW7.jpg', 'videos/1327-VnfUNW7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0259', 'close-grip push-up', 'upper arms', 'upper arms', 'body weight', 'Start in a high plank position with your hands placed close together, directly under your shoulders. Engage your core and lower your body towards the ground, keeping your elbows close to your sides. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de plancha alta con las manos juntas, directamente debajo de los hombros. Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0259-x6KpKpq.jpg', 'videos/0259-x6KpKpq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2398', 'close-grip push-up (on knees)', 'upper arms', 'upper arms', 'body weight', 'Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart. Lower your upper body towards the ground by bending your elbows, keeping them close to your sides. Pause for a moment when your chest is just above the ground. Push through your palms to straighten your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Comienza apoyándote sobre las manos y las rodillas, con las manos separadas a la altura de los hombros y las rodillas separadas a la altura de las caderas. Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Haz una pausa breve cuando tu pecho esté justo por encima del suelo. Empuja con las palmas para estirar los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/2398-v3vLFW0.jpg', 'videos/2398-v3vLFW0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0260', 'cocoons', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/0260-SLKj2pX.jpg', 'videos/0260-SLKj2pX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1468', 'crab twist toe touch', 'waist', 'waist', 'body weight', 'Start by sitting on the ground with your knees bent and feet flat on the floor. Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground. Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes. Return to the starting position and repeat on the other side. Continue alternating sides for the desired number of repetitions.', 'Comienza sentado en el suelo con las rodillas flexionadas y los pies planos en el suelo. Coloca las manos detrás de ti, con los dedos apuntando hacia los pies, y levanta las caderas del suelo. Extiende una pierna recta frente a ti mientras al mismo tiempo llevas la mano contraria hacia los dedos del pie. Regresa a la posición inicial y repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","hip flexors"]'::jsonb, 'abs', 'images/1468-xgsGFVM.jpg', 'videos/1468-xgsGFVM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0262', 'cross body crunch', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat on the other side, bringing your left elbow towards your right knee. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta la parte superior del cuerpo del suelo y gira para llevar el codo derecho hacia la rodilla izquierda. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite en el otro lado, llevando el codo izquierdo hacia la rodilla derecha. Repite el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0262-rbu5UUb.jpg', 'videos/0262-rbu5UUb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0267', 'crunch (hands overhead)', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms straight above your head. Engaging your abs, lift your upper body off the ground, curling forward towards your knees. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende los brazos rectos por encima de la cabeza. Activando el abdomen, levanta la parte superior del cuerpo del suelo, flexionándote hacia adelante en dirección a las rodillas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0267-kjJ3VoQ.jpg', 'videos/0267-kjJ3VoQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0271', 'crunch (on stability ball)', 'waist', 'waist', 'stability ball', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Lie back on the ball until your lower back is supported and your upper body is parallel to the floor. Place your hands behind your head or across your chest. Engage your abs and lift your upper body towards your knees, curling your torso forward. Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso hacia adelante. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0271-MCUhf1F.jpg', 'videos/0271-MCUhf1F.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0272', 'crunch (on stability ball, arms straight)', 'waist', 'waist', 'stability ball', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Lie back on the ball until your lower back is supported and your upper body is parallel to the floor. Place your hands behind your head or cross them over your chest. Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del balón, flexionando los hombros hacia las caderas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0272-Sn8wxAI.jpg', 'videos/0272-Sn8wxAI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0274', 'crunch floor', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engage your abs and lift your shoulders off the ground, curling forward towards your knees. Pause for a moment at the top, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activa el abdomen y levanta los hombros del suelo, flexionándote hacia adelante en dirección a las rodillas. Haz una pausa breve en la parte alta, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0274-TFqbd8t.jpg', 'videos/0274-TFqbd8t.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3016', 'curl-up', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/3016-g2oKspu.jpg', 'videos/3016-g2oKspu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3769', 'curtsey squat', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart. Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg. Bend both knees as if you were curtsying, lowering your body towards the ground. Keep your torso upright and your weight on your front foot. Push through your front foot to return to the starting position. Repeat on the other side, stepping diagonally behind and across your body with your left foot.', 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso en diagonal hacia atrás y a través de tu cuerpo con el pie derecho, cruzándolo detrás de la pierna izquierda. Flexiona ambas rodillas como si hicieras una reverencia, bajando el cuerpo hacia el suelo. Mantén el torso erguido y el peso sobre el pie delantero. Empuja con el pie delantero para regresar a la posición inicial. Repite en el otro lado, dando un paso en diagonal hacia atrás y a través de tu cuerpo con el pie izquierdo.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3769-gUjqdei.jpg', 'videos/3769-gUjqdei.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2331', 'cycle cross trainer', 'cardio', 'cardio', 'leverage machine', 'Adjust the seat height and position yourself on the cycle cross trainer. Place your feet on the pedals and grip the handlebars. Start pedaling in a smooth and controlled motion. Maintain a steady pace and increase the resistance if desired. Continue pedaling for the desired duration of your cardio workout.', 'Ajusta la altura del asiento y colócate en la bicicleta elíptica. Coloca los pies en los pedales y sujeta el manillar. Comienza a pedalear con un movimiento suave y controlado. Mantén un ritmo constante y aumenta la resistencia si lo deseas. Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular.', 'quadriceps', '["quadriceps","hamstrings","glutes"]'::jsonb, 'cardiovascular system', 'images/2331-XSCHmiI.jpg', 'videos/2331-XSCHmiI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0276', 'dead bug', 'waist', 'waist', 'body weight', 'Lie flat on your back with your arms extended towards the ceiling. Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees. Engage your core and lower back to press your lower back into the ground. Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor. Pause for a moment, then return to the starting position. Repeat the movement with your left arm and right leg. Continue alternating sides for the desired number of repetitions.', 'Túmbate boca arriba con los brazos extendidos hacia el techo. Flexiona las rodillas y levanta las piernas del suelo, formando un ángulo de 90 grados en las caderas y las rodillas. Activa el core y la zona lumbar para presionar la zona lumbar contra el suelo. Baja lentamente el brazo derecho y la pierna izquierda hacia el suelo, manteniéndolos rectos y justo por encima del suelo. Haz una pausa breve y luego vuelve a la posición inicial. Repite el movimiento con el brazo izquierdo y la pierna derecha. Continúa alternando lados durante el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/0276-iny3m5y.jpg', 'videos/0276-iny3m5y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0277', 'decline crunch', 'waist', 'waist', 'body weight', 'Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle. Place your hands behind your head or across your chest. Engage your abs and lift your upper body towards your knees, curling your torso. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas en un ángulo de 90 grados. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0277-9Ap7miY.jpg', 'videos/0277-9Ap7miY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0279', 'decline push-up', 'chest', 'chest', 'body weight', 'Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface. Keep your body in a straight line from head to toe, engaging your core muscles. Lower your chest towards the ground by bending your elbows, keeping them close to your body. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Coloca las manos en el suelo un poco más separadas que el ancho de los hombros, con los pies elevados sobre una superficie estable. Mantén el cuerpo en línea recta de la cabeza a los pies, activando los músculos del core. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0279-i5cEhka.jpg', 'videos/0279-i5cEhka.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0282', 'decline sit-up', 'waist', 'waist', 'body weight', 'Lie on a decline bench with your feet secured and your knees bent. Place your hands behind your head or across your chest. Engage your abs and lift your upper body off the bench, curling forward towards your knees. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del banco, flexionándote hacia adelante en dirección a las rodillas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/0282-QLL2gdc.jpg', 'videos/0282-QLL2gdc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1274', 'deep push up', 'chest', 'chest', 'dumbbell', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line. Lower your chest towards the ground by bending your elbows, keeping them close to your body. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1274-vptOQ4N.jpg', 'videos/1274-vptOQ4N.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0283', 'diamond push-up', 'upper arms', 'upper arms', 'body weight', 'Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers. Keep your body in a straight line from head to toe, engaging your core and glutes. Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de plancha alta con las manos juntas, formando una figura de diamante con los pulgares y los índices. Mantén el cuerpo en línea recta de la cabeza a los pies, activando el core y los glúteos. Baja el pecho hacia la figura de diamante formada por tus manos, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0283-soIB2rj.jpg', 'videos/0283-soIB2rj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0284', 'donkey calf raise', 'lower legs', 'lower legs', 'body weight', 'Stand with your toes on an elevated surface, such as a step or block. Place your hands on a stable support, such as a wall or railing, for balance. Raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con las puntas de los pies sobre una superficie elevada, como un escalón o un bloque. Coloca las manos en un soporte estable, como una pared o un pasamanos, para mantener el equilibrio. Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/0284-u5ESqzH.jpg', 'videos/0284-u5ESqzH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1275', 'drop push up', 'chest', 'chest', 'body weight', 'Start in a high plank position with your hands slightly wider than shoulder-width apart. Lower your chest towards the ground, keeping your elbows close to your body. Once your chest is just above the ground, quickly drop your knees to the ground. Push yourself back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. Una vez que tu pecho esté justo por encima del suelo, baja rápidamente las rodillas al suelo. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1275-Q497lAE.jpg', 'videos/1275-Q497lAE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0285', 'dumbbell alternate biceps curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions, alternating arms.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado, alternando los brazos.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0285-BU15nH4.jpg', 'videos/0285-BU15nH4.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2403', 'dumbbell alternate biceps curl (with arm blaster)', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward. Place the arm blaster on your upper arms, ensuring a secure fit. Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat the movement with the opposite arm. Continue alternating arms for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Coloca el soporte para brazos en la parte superior de tus brazos, asegurándote de que quede bien ajustado. Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna hacia el hombro mientras contraes el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo contrario. Continúa alternando los brazos durante el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/2403-CfKsRbG.jpg', 'videos/2403-CfKsRbG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1646', 'dumbbell alternate hammer preacher curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended. Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the recommended amount of repetitions.', 'Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos completamente extendidos. Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1646-fy7Tgy4.jpg', 'videos/1646-fy7Tgy4.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1647', 'dumbbell alternate preacher curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a preacher bench with a dumbbell in each hand, palms facing up. Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend. Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps. Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position. Repeat the movement with your left arm. Continue alternating arms for the desired number of repetitions.', 'Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba. Apoya la parte superior de los brazos en la almohadilla del banco scott, permitiendo que los brazos se extiendan completamente. Manteniendo los brazos superiores quietos, exhala y flexiona la mancuerna en tu mano derecha mientras contraes el bíceps. Continúa flexionando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo izquierdo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1647-NlfIbzq.jpg', 'videos/1647-NlfIbzq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1648', 'dumbbell alternate seated hammer curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down. Keep your back straight and your elbows close to your torso. Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position. Repeat the movement with your left arm. Continue alternating arms for the desired number of repetitions.', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos hacia abajo. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo izquierdo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1648-6em2Dxj.jpg', 'videos/1648-6em2Dxj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0286', 'dumbbell alternate side press', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height. Press one dumbbell overhead while keeping the other dumbbell at shoulder height. Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros. Empuja una mancuerna por encima de la cabeza mientras mantienes la otra mancuerna a la altura del hombro. Baja la mancuerna empujada de vuelta a la altura del hombro mientras empujas la otra mancuerna por encima de la cabeza. Continúa alternando lados durante el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0286-izMnLqz.jpg', 'videos/0286-izMnLqz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1649', 'dumbbell alternating bicep curl with leg raised on exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward. Place an exercise ball behind you and position one foot on top of it, keeping your balance. With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary. Lower the dumbbell back down to the starting position and repeat with the other arm. Continue alternating arms for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Coloca un balón de ejercicio detrás de ti y apoya un pie sobre él, manteniendo el equilibrio. Con los brazos completamente extendidos y los codos cerca de los costados, flexiona una mancuerna hacia el hombro mientras mantienes el brazo superior quieto. Baja la mancuerna de vuelta a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/1649-Zwiw7XR.jpg', 'videos/1649-Zwiw7XR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1650', 'dumbbell alternating seated bicep curl on exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing forward and your arms fully extended. Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder. Inhale and slowly lower the dumbbell back to the starting position. Repeat the curl with the other arm. Continue alternating curls for the desired number of repetitions.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna mientras rotas el antebrazo hasta que la palma quede frente al hombro. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite la flexión con el otro brazo. Continúa alternando flexiones el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1650-J74XlNf.jpg', 'videos/1650-J74XlNf.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2137', 'dumbbell arnold press', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent. Press the dumbbells upward until your arms are fully extended and your palms are facing forward. Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura del hombro, con las palmas hacia tu cuerpo y los codos flexionados. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos y las palmas miren hacia adelante. Rota las muñecas mientras levantas, de modo que las palmas miren hacia adelante en la parte alta del movimiento. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper chest"]'::jsonb, 'delts', 'images/2137-Xy4jlWA.jpg', 'videos/2137-Xy4jlWA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0287', 'dumbbell arnold press v. 2', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent. Press the dumbbells upward until your arms are fully extended and your palms are facing forward. Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura del hombro, con las palmas hacia tu cuerpo y los codos flexionados. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos y las palmas miren hacia adelante. Rota las muñecas mientras levantas, de modo que las palmas terminen mirando hacia adelante en la parte alta del movimiento. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper chest"]'::jsonb, 'delts', 'images/0287-eOrFCnx.jpg', 'videos/0287-eOrFCnx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0288', 'dumbbell around pullover', 'chest', 'chest', 'dumbbell', 'Lie flat on a bench with your head at one end and your feet firmly on the ground. Hold a dumbbell with both hands and extend your arms straight above your chest. Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion. Pause for a moment at the bottom, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza en un movimiento de arco. Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","latissimus dorsi"]'::jsonb, 'pectorals', 'images/0288-vi8EhoE.jpg', 'videos/0288-vi8EhoE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0289', 'dumbbell bench press', 'chest', 'chest', 'dumbbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest. Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle. Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta una mancuerna en cada mano, con las palmas hacia adelante y los brazos extendidos por encima del pecho. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Haz una pausa breve, luego empuja las mancuernas de vuelta hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0289-SpYC0Kp.jpg', 'videos/0289-SpYC0Kp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0290', 'dumbbell bench seated press', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with a dumbbell in each hand, resting on your thighs. Lean back and position the dumbbells to the sides of your chest, palms facing forward. Press the dumbbells upward until your arms are fully extended. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos. Reclínate hacia atrás y coloca las mancuernas a los lados del pecho, con las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'delts', 'images/0290-3d7wHyd.jpg', 'videos/0290-3d7wHyd.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0291', 'dumbbell bench squat', 'upper legs', 'upper legs', 'dumbbell', 'Place a dumbbell on the ground in front of a bench. Stand facing away from the bench with your feet shoulder-width apart. Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight. Once your glutes touch the bench, push through your heels to stand back up to the starting position. Repeat for the desired number of repetitions.', 'Coloca una mancuerna en el suelo frente a un banco. Ponte de pie de espaldas al banco con los pies separados a la altura de los hombros. Flexiona las rodillas y las caderas para bajar hacia el banco, manteniendo el pecho elevado y la espalda recta. Una vez que los glúteos toquen el banco, empuja con los talones para volver a ponerte de pie en la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0291-mnzcrIB.jpg', 'videos/0291-mnzcrIB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0293', 'dumbbell bent over row', 'back', 'back', 'dumbbell', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body. Bend forward at the hips, keeping your back straight and your core engaged. Let your arms hang straight down towards the floor, with your elbows slightly bent. Pull the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Deja que los brazos cuelguen rectos hacia el suelo, con los codos ligeramente flexionados. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0293-BJ0Hz5L.jpg', 'videos/0293-BJ0Hz5L.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1651', 'dumbbell bicep curl lunge with bowling motion', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward. Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position. As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body. At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball. Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down. Repeat the lunge and curl motion, this time rotating your torso to the left. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante. Da un paso adelante con el pie derecho, flexionando la rodilla derecha y bajando el cuerpo a una posición de zancada. Mientras avanzas en la zancada, flexiona las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo. En la parte baja de la zancada, gira el torso hacia la derecha, como si estuvieras lanzando una bola de boliche. Invierte el movimiento, retrocediendo con el pie derecho y regresando a la posición inicial mientras bajas las mancuernas de nuevo. Repite el movimiento de zancada y flexión, esta vez girando el torso hacia la izquierda. Continúa alternando lados durante el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/1651-1VpF8db.jpg', 'videos/1651-1VpF8db.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1652', 'dumbbell bicep curl on exercise ball with leg raised', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing forward and your arms fully extended. Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides. Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position. While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise. Repeat for the desired number of repetitions, then switch legs and repeat.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Flexiona lentamente las mancuernas hacia los hombros, manteniendo los codos cerca de los costados. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Mientras realizas el curl de bíceps, levanta una pierna del suelo y mantenla en el aire durante todo el ejercicio. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/1652-2NImIAG.jpg', 'videos/1652-2NImIAG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1653', 'dumbbell bicep curl with stork stance', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward. Extend one leg behind you, balancing on the toes of that foot. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Extiende una pierna hacia atrás, equilibrándote sobre los dedos de ese pie. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1653-uSkDMYl.jpg', 'videos/1653-uSkDMYl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0294', 'dumbbell biceps curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0294-NbVPDMW.jpg', 'videos/0294-NbVPDMW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2401', 'dumbbell biceps curl (with arm blaster)', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing forward. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona las pesas mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/2401-nlJsbkW.jpg', 'videos/2401-nlJsbkW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1654', 'dumbbell biceps curl reverse', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1654-nFc4FyV.jpg', 'videos/1654-nFc4FyV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1655', 'dumbbell biceps curl squat', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward. Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante. Manteniendo la espalda recta y los codos cerca de los costados, exhala y flexiona las mancuernas hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1655-niXESDw.jpg', 'videos/1655-niXESDw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1656', 'dumbbell biceps curl v sit on bosu ball', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un bosu con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos hacia abajo a los lados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/1656-H1XAdpk.jpg', 'videos/1656-H1XAdpk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1201', 'dumbbell burpee', 'cardio', 'cardio', 'dumbbell', 'Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand. Lower your body into a squat position, placing the dumbbells on the ground in front of you. Kick your feet back into a push-up position, keeping your body in a straight line. Perform a push-up, bending your elbows and lowering your chest towards the ground. Jump your feet back towards your hands, landing in a squat position. Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders. Press the dumbbells overhead, fully extending your arms. Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros y una mancuerna en cada mano. Baja el cuerpo a una posición de sentadilla, colocando las mancuernas en el suelo frente a ti. Lleva los pies hacia atrás a una posición de flexión de brazos, manteniendo el cuerpo en línea recta. Realiza una flexión de brazos, flexionando los codos y bajando el pecho hacia el suelo. Salta con los pies hacia tus manos, aterrizando en una posición de sentadilla. Ponte de pie de forma explosiva, levantando las mancuernas del suelo y llevándolas a los hombros. Empuja las mancuernas por encima de la cabeza, extendiendo completamente los brazos. Baja las mancuernas de vuelta a los hombros y repite toda la secuencia el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves","shoulders","triceps","core"]'::jsonb, 'cardiovascular system', 'images/1201-0JtKWum.jpg', 'videos/1201-0JtKWum.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0295', 'dumbbell clean', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Bend your knees and lower your hips into a squat position, keeping your back straight and chest up. Explosively extend your hips and knees, driving through your heels to jump off the ground. As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body. Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up. Lower the dumbbells back down to the starting position by reversing the movement. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Extiende las caderas y las rodillas de forma explosiva, empujando con los talones para saltar del suelo. Mientras saltas, encoge los hombros y tira de las mancuernas hacia arriba, hacia los hombros, manteniéndolas cerca del cuerpo. Atrapa las mancuernas a la altura de los hombros, con los codos apuntando hacia adelante y las palmas hacia arriba. Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","calves"]'::jsonb, 'glutes', 'images/0295-7Hg55JG.jpg', 'videos/0295-7Hg55JG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1731', 'dumbbell close grip press', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a flat bench with a dumbbell in each hand, resting on your thighs. Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest. As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells. After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.', 'Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos. Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros. Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial. Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho. Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial. Asegúrate de usar solo los tríceps y no usar los antebrazos ni los bíceps para ayudar a levantar las mancuernas. Después de una pausa de un segundo en la posición contraída, repite el movimiento el número de repeticiones prescrito.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1731-7jGOBF3.jpg', 'videos/1731-7jGOBF3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0296', 'dumbbell close-grip press', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a flat bench with a dumbbell in each hand, resting on your thighs. Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest. As you exhale, use your triceps to lift the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos. Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros. Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial. Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho. Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0296-RxayqAZ.jpg', 'videos/0296-RxayqAZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0297', 'dumbbell concentration curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh. Fully extend your arm and hold the dumbbell with an underhand grip. Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco con las piernas separadas y una mancuerna en una mano, apoyando el codo en la parte interna del muslo. Extiende completamente el brazo y sujeta la mancuerna con un agarre supino. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro mientras contraes el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0297-gvsWLQw.jpg', 'videos/0297-gvsWLQw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3635', 'dumbbell contralateral forward lunge', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step forward with your right foot, keeping your back straight and core engaged. Lower your body by bending both knees until your right thigh is parallel to the ground. Push through your right heel to return to the starting position. Repeat with your left leg. Alternate legs for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso adelante con el pie derecho, manteniendo la espalda recta y el core activado. Baja el cuerpo flexionando ambas rodillas hasta que el muslo derecho quede paralelo al suelo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda. Alterna las piernas el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3635-ecl28tP.jpg', 'videos/3635-ecl28tP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0298', 'dumbbell cross body hammer curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your body. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona los brazos contrayendo los bíceps, llevando las mancuernas a través del cuerpo hacia el hombro opuesto. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0298-Qyk5J3p.jpg', 'videos/0298-Qyk5J3p.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1657', 'dumbbell cross body hammer curl v. 2', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your body. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona los brazos contrayendo los bíceps, acercando las mancuernas lo más posible al hombro opuesto. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1657-HDYiZcY.jpg', 'videos/1657-HDYiZcY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0299', 'dumbbell cuban press', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down. Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended. Rotate your wrists so that your palms are facing forward. Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo. Manteniendo el core activado y los codos ligeramente flexionados, empuja las mancuernas hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos. Gira las muñecas de modo que las palmas queden mirando hacia adelante. Baja lentamente las mancuernas a la posición inicial, girando las muñecas de vuelta a la posición inicial mientras lo haces. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0299-QfAKy1G.jpg', 'videos/0299-QfAKy1G.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2136', 'dumbbell cuban press v. 2', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down. Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended. Rotate your wrists so that your palms are facing forward. Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo. Manteniendo el core activado y la espalda recta, empuja las mancuernas directamente hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos. Gira las muñecas de modo que las palmas queden mirando hacia adelante. Baja las mancuernas de nuevo hasta la altura de los hombros, girando las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/2136-BqgCRif.jpg', 'videos/2136-BqgCRif.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0300', 'dumbbell deadlift', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, toes pointing forward. Hold a dumbbell in each hand, palms facing your body, arms extended downwards. Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight. Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante. Sostén una mancuerna en cada mano, con las palmas hacia el cuerpo y los brazos extendidos hacia abajo. Flexiona las caderas y las rodillas, bajando las mancuernas hacia el suelo mientras mantienes la espalda recta. Empuja con los talones y extiende las caderas y las rodillas, levantando las mancuernas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0300-nUwVh7b.jpg', 'videos/0300-nUwVh7b.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0301', 'dumbbell decline bench press', 'chest', 'chest', 'dumbbell', 'Lie down on a decline bench with your feet secured and your head lower than your hips. Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward. Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle. Push the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Sostén una mancuerna en cada mano y extiende los brazos rectos hacia arriba por encima del pecho, con las palmas hacia adelante. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0301-DwhEmmE.jpg', 'videos/0301-DwhEmmE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0302', 'dumbbell decline fly', 'chest', 'chest', 'dumbbell', 'Lie on a decline bench with your feet secured and your head lower than your hips. Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'pectorals', 'images/0302-xXm4nYq.jpg', 'videos/0302-xXm4nYq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0303', 'dumbbell decline hammer press', 'chest', 'chest', 'dumbbell', 'Lie on a decline bench with your feet secured and your head lower than your hips. Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest. Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent. Press the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho. Baja las mancuernas a los lados del pecho, manteniendo los codos ligeramente flexionados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0303-1qrWgZ2.jpg', 'videos/0303-1qrWgZ2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1276', 'dumbbell decline one arm fly', 'chest', 'chest', 'dumbbell', 'Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh. Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso. Rotate your wrist so that the palm of your hand is facing forward. As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest. Exhale and use your chest muscles to bring the dumbbell back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Túmbate en un banco declinado con una mancuerna en una mano, apoyándola sobre el muslo. Usando el muslo para ayudar a levantar la mancuerna, álzala hasta la altura de los hombros con la palma mirando hacia el torso. Gira la muñeca de modo que la palma de la mano quede mirando hacia adelante. Mientras inhalas, baja la mancuerna lentamente hacia el lado hasta sentir un estiramiento en el pecho. Exhala y usa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders"]'::jsonb, 'pectorals', 'images/1276-NL6YBwN.jpg', 'videos/1276-NL6YBwN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1617', 'dumbbell decline one arm hammer press', 'upper arms', 'upper arms', 'dumbbell', 'Lie on a decline bench with a dumbbell in one hand, resting on your chest. Extend your arm straight up, keeping your elbow slightly bent. Lower the dumbbell down towards your shoulder, keeping your elbow close to your body. Press the dumbbell back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho. Extiende el brazo recto hacia arriba, manteniendo el codo ligeramente flexionado. Baja la mancuerna hacia el hombro, manteniendo el codo cerca del cuerpo. Empuja la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1617-SHUMp5H.jpg', 'videos/1617-SHUMp5H.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0305', 'dumbbell decline shrug', 'back', 'back', 'dumbbell', 'Set up a decline bench at a 45-degree angle. Lie face down on the bench with your chest and stomach resting against it. Hold a dumbbell in each hand with your arms fully extended towards the floor. Keeping your arms straight, raise your shoulders towards your ears as high as possible. Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta un banco declinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él. Sostén una mancuerna en cada mano con los brazos completamente extendidos hacia el suelo. Manteniendo los brazos rectos, levanta los hombros hacia las orejas lo más alto posible. Mantén la contracción por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","rhomboids"]'::jsonb, 'traps', 'images/0305-cwsAI4G.jpg', 'videos/0305-cwsAI4G.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0304', 'dumbbell decline shrug v. 2', 'back', 'back', 'dumbbell', 'Set up a decline bench at a 45-degree angle. Lie face down on the bench with your chest and stomach resting on it. Hold a dumbbell in each hand with your palms facing each other and your arms fully extended. Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together. Hold the contraction for a brief pause, then lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta un banco declinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados sobre él. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos completamente extendidos. Manteniendo los brazos rectos, levanta los hombros lo más alto posible mientras juntas los omóplatos. Mantén la contracción durante una breve pausa, luego baja las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","rhomboids"]'::jsonb, 'traps', 'images/0304-bRlbdjK.jpg', 'videos/0304-bRlbdjK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0306', 'dumbbell decline triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other. Extend your arms fully, keeping your elbows close to your head. Lower the dumbbells slowly behind your head, bending your elbows. Pause for a moment, then raise the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con la cabeza más baja que los pies y sostén una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende completamente los brazos, manteniendo los codos cerca de la cabeza. Baja lentamente las mancuernas detrás de la cabeza, flexionando los codos. Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0306-OTgkHwR.jpg', 'videos/0306-OTgkHwR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0307', 'dumbbell decline twist fly', 'chest', 'chest', 'dumbbell', 'Lie down on a decline bench with your head lower than your hips. Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement. Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con la cabeza más baja que las caderas. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento. Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0307-reFHapa.jpg', 'videos/0307-reFHapa.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1437', 'dumbbell finger curls', 'lower arms', 'lower arms', 'dumbbell', 'Sit on a bench or chair with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up. Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers. Repeat for the desired number of repetitions, then switch to the other hand.', 'Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta. Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo, con la palma hacia arriba. Deja que la mancuerna ruede hacia las puntas de los dedos, luego flexiona los dedos para volver a enrollarla hacia arriba. Repite el número de repeticiones deseado, luego cambia a la otra mano.', 'wrist flexors', '["wrist flexors","wrist extensors"]'::jsonb, 'forearms', 'images/1437-mtXengz.jpg', 'videos/1437-mtXengz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0308', 'dumbbell fly', 'chest', 'chest', 'dumbbell', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other. Extend your arms straight up over your chest, with a slight bend in your elbows. Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'pectorals', 'images/0308-yz9nUhF.jpg', 'videos/0308-yz9nUhF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1277', 'dumbbell fly on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball and hold a dumbbell in each hand. Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball. Extend your arms straight up above your chest, palms facing each other. Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad y sostén una mancuerna en cada mano. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Extiende los brazos rectos por encima del pecho, con las palmas enfrentadas entre sí. Flexiona ligeramente los codos y baja los brazos hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego invierte el movimiento y contrae los músculos del pecho mientras llevas las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1277-Lt3iWnf.jpg', 'videos/1277-Lt3iWnf.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1732', 'dumbbell forward lunge triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step forward with your right foot, lowering your body into a lunge position. Keep your back straight and your chest up. Extend your arms straight overhead, keeping your elbows close to your ears. Lower the dumbbells behind your head by bending your elbows. Pause for a moment, then straighten your arms to return to the starting position. Repeat the movement for the desired number of repetitions, then switch legs and repeat.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mantén la espalda recta y el pecho elevado. Extiende los brazos rectos por encima de la cabeza, manteniendo los codos cerca de las orejas. Baja las mancuernas detrás de la cabeza flexionando los codos. Haz una pausa por un momento, luego estira los brazos para volver a la posición inicial. Repite el movimiento el número de repeticiones deseado, luego cambia de pierna y repite.', 'shoulders', '["shoulders","core"]'::jsonb, 'triceps', 'images/1732-XalXcvM.jpg', 'videos/1732-XalXcvM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0310', 'dumbbell front raise', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs. Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos. Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","trapezius"]'::jsonb, 'delts', 'images/0310-3eGE2JC.jpg', 'videos/0310-3eGE2JC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0309', 'dumbbell front raise v. 2', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs. Keep your back straight and engage your core. Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos. Mantén la espalda recta y activa el core. Levanta lentamente las mancuernas frente a ti, con los brazos rectos, hasta que queden a la altura de los hombros. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","biceps"]'::jsonb, 'delts', 'images/0309-Rr7S3yg.jpg', 'videos/0309-Rr7S3yg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0311', 'dumbbell full can lateral raise', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body. Keep your back straight and engage your core. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","rotator cuff"]'::jsonb, 'delts', 'images/0311-AQ0mC4Y.jpg', 'videos/0311-AQ0mC4Y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1760', 'dumbbell goblet squat', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands. Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna verticalmente contra el pecho con ambas manos. Manteniendo el pecho erguido y el core activado, baja el cuerpo a una posición de sentadilla empujando las caderas hacia atrás y flexionando las rodillas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/1760-yn8yg1r.jpg', 'videos/1760-yn8yg1r.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0313', 'dumbbell hammer curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Then, inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the recommended amount of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0313-slDvUAU.jpg', 'videos/0313-slDvUAU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1659', 'dumbbell hammer curl on exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing your body and your arms fully extended. Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1659-fY68AyX.jpg', 'videos/1659-fY68AyX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0312', 'dumbbell hammer curl v. 2', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Then, inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the recommended amount of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0312-2NpxjC1.jpg', 'videos/0312-2NpxjC1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2402', 'dumbbell hammer curls (with arm blaster)', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Then, inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the recommended amount of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo el brazo superior quieto, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/2402-GNhAeJ0.jpg', 'videos/2402-GNhAeJ0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1664', 'dumbbell high curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing forward. Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Mantén los brazos superiores quietos y flexiona las mancuernas lo más alto posible contrayendo los bíceps. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1664-qAmNMJY.jpg', 'videos/1664-qAmNMJY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3545', 'dumbbell incline alternate press', 'chest', 'chest', 'dumbbell', 'Sit on an incline bench with a dumbbell in each hand, resting on your thighs. Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward. Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward. Push the dumbbells up with your chest and shoulders, extending your arms fully. Lower the dumbbells back down to the starting position, keeping your elbows slightly bent. Repeat for the desired number of repetitions, alternating arms.', 'Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate en el banco y usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Una vez a la altura de los hombros, gira las muñecas de modo que las palmas de las manos queden mirando hacia adelante. Empuja las mancuernas hacia arriba con el pecho y los hombros, extendiendo completamente los brazos. Baja las mancuernas de nuevo hasta la posición inicial, manteniendo los codos ligeramente flexionados. Repite el número de repeticiones deseado, alternando los brazos.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/3545-TVdivgY.jpg', 'videos/3545-TVdivgY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0314', 'dumbbell incline bench press', 'chest', 'chest', 'dumbbell', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench. Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height. Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle. Push the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con los pies apoyados en el suelo y la espalda firmemente apoyada contra el banco. Sostén una mancuerna en cada mano, con las palmas hacia adelante, y levántalas hasta la altura de los hombros. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0314-ns0SIbU.jpg', 'videos/0314-ns0SIbU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0315', 'dumbbell incline biceps curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0315-F3xgbjF.jpg', 'videos/0315-F3xgbjF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0316', 'dumbbell incline breeding', 'chest', 'chest', 'dumbbell', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your back against the pad and feet flat on the ground. Hold a dumbbell in each hand with an overhand grip, palms facing forward. Start with your arms fully extended, perpendicular to the ground. Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle. Pause for a moment at the bottom, then push the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo. Sostén una mancuerna en cada mano con agarre prono, con las palmas hacia adelante. Comienza con los brazos completamente extendidos, perpendiculares al suelo. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0316-B3Rxp6L.jpg', 'videos/0316-B3Rxp6L.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0318', 'dumbbell incline curl', 'upper arms', 'upper arms', 'dumbbell', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward. Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adelante. Apoya los brazos superiores en el banco inclinado y deja que los codos cuelguen hacia abajo, extendiendo completamente los brazos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0318-ae9UoXQ.jpg', 'videos/0318-ae9UoXQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0317', 'dumbbell incline curl v. 2', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0317-RaflbWD.jpg', 'videos/0317-RaflbWD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0319', 'dumbbell incline fly', 'chest', 'chest', 'dumbbell', 'Set an incline bench to a 45-degree angle. Sit on the bench with a dumbbell in each hand, palms facing each other. Lie back on the bench and press the dumbbells up to the starting position, directly above your chest. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'pectorals', 'images/0319-ESOd5Pl.jpg', 'videos/0319-ESOd5Pl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1278', 'dumbbell incline fly on exercise ball', 'chest', 'chest', 'dumbbell', 'Set up an incline bench at a 45-degree angle. Sit on an exercise ball and roll forward until your upper back is resting on the incline bench. Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el banco inclinado. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'pectorals', 'images/1278-HYe1ZqR.jpg', 'videos/1278-HYe1ZqR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0320', 'dumbbell incline hammer curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended. Keep your back against the bench and your feet flat on the floor. While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia el torso y los brazos completamente extendidos. Mantén la espalda contra el banco y los pies apoyados en el suelo. Manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0320-ByX0WxV.jpg', 'videos/0320-ByX0WxV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0321', 'dumbbell incline hammer press', 'chest', 'chest', 'dumbbell', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs. Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other. Press the dumbbells up and away from your body until your arms are fully extended. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate en el banco y coloca las mancuernas a la altura de los hombros con las palmas enfrentadas entre sí. Empuja las mancuernas hacia arriba y alejándolas del cuerpo hasta que los brazos queden completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0321-PG1kcIb.jpg', 'videos/0321-PG1kcIb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1618', 'dumbbell incline hammer press on exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with a dumbbell in each hand, palms facing each other. Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball. Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides. Press the dumbbells up and slightly inward, keeping your palms facing each other. Extend your arms fully, squeezing your triceps at the top of the movement. Slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Camina con los pies hacia adelante y baja el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados. Empuja las mancuernas hacia arriba y ligeramente hacia adentro, manteniendo las palmas enfrentadas entre sí. Extiende completamente los brazos, contrayendo los tríceps en la parte superior del movimiento. Baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1618-wkgnGfb.jpg', 'videos/1618-wkgnGfb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0322', 'dumbbell incline inner biceps curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an incline bench with a dumbbell in each hand, palms facing each other. Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Apoya los brazos superiores en el banco, permitiendo que los codos cuelguen hacia abajo y las palmas miren hacia adelante. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0322-LCtQPn8.jpg', 'videos/0322-LCtQPn8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1279', 'dumbbell incline one arm fly', 'chest', 'chest', 'dumbbell', 'Adjust the incline bench to a 30-45 degree angle. Sit on the bench with a dumbbell in one hand, resting it on your thigh. Lie back on the bench, keeping your feet flat on the ground. Hold the dumbbell with your arm extended straight up over your chest. Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow. Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ajusta el banco inclinado a un ángulo de 30-45 grados. Siéntate en el banco con una mancuerna en una mano, apoyándola sobre el muslo. Recuéstate en el banco, manteniendo los pies apoyados en el suelo. Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho. Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo. Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento para llevar la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/1279-Gw2HFvW.jpg', 'videos/1279-Gw2HFvW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1280', 'dumbbell incline one arm fly on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball with a dumbbell in one hand. Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball. Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards. Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow. Pause for a moment when your arm is parallel to the ground. Engage your chest muscles to bring the dumbbell back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho, con la palma hacia adentro. Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo. Haz una pausa por un momento cuando el brazo esté paralelo al suelo. Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders"]'::jsonb, 'pectorals', 'images/1280-LLNh6q5.jpg', 'videos/1280-LLNh6q5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1619', 'dumbbell incline one arm hammer press', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an incline bench with a dumbbell in one hand, resting on your thigh. Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height. Rotate your wrist so that your palm is facing inward, towards your body. Press the dumbbell up and away from your body, extending your arm fully. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo. Recuéstate en el banco y usa el muslo para ayudar a levantar la mancuerna hasta la altura de los hombros. Gira la muñeca de modo que la palma quede mirando hacia adentro, hacia el cuerpo. Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders","chest"]'::jsonb, 'triceps', 'images/1619-LL1UiTX.jpg', 'videos/1619-LL1UiTX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1620', 'dumbbell incline one arm hammer press on exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with a dumbbell in one hand. Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball. Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle. Press the dumbbell up towards the ceiling, straightening your arm. Lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén la mancuerna con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados. Empuja la mancuerna hacia el techo, estirando el brazo. Baja la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders","chest"]'::jsonb, 'triceps', 'images/1620-jDnrkar.jpg', 'videos/1620-jDnrkar.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0323', 'dumbbell incline one arm lateral raise', 'shoulders', 'shoulders', 'dumbbell', 'Sit on an incline bench with a dumbbell in one hand, resting it on your thigh. Lean forward and position your upper arm against the inside of your thigh. Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down. Continue lifting until your arm is parallel to the floor. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Siéntate en un banco inclinado con una mancuerna en una mano, apoyándola sobre el muslo. Inclínate hacia adelante y coloca el brazo superior contra la parte interna del muslo. Levanta la mancuerna hacia el lado, manteniendo el brazo ligeramente flexionado y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'trapezius', '["trapezius","triceps"]'::jsonb, 'delts', 'images/0323-aTNKZiC.jpg', 'videos/0323-aTNKZiC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1281', 'dumbbell incline one arm press', 'chest', 'chest', 'dumbbell', 'Sit on an incline bench with a dumbbell in one hand, resting on your thigh. Lie back on the bench and position the dumbbell at shoulder level, palm facing forward. Press the dumbbell upward and slightly inward, extending your arm fully. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo. Recuéstate en el banco y coloca la mancuerna a la altura del hombro, con la palma hacia adelante. Empuja la mancuerna hacia arriba y ligeramente hacia adentro, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1281-rDAiRf9.jpg', 'videos/1281-rDAiRf9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1282', 'dumbbell incline one arm press on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground. Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball. Hold the dumbbell at shoulder height with your palm facing forward. Press the dumbbell upward until your arm is fully extended. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano, con los pies apoyados en el suelo. Camina lentamente con los pies hacia adelante, haciendo rodar el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén la mancuerna a la altura del hombro con la palma hacia adelante. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1282-Bg5JKSH.jpg', 'videos/1282-Bg5JKSH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0324', 'dumbbell incline palm-in press', 'chest', 'chest', 'dumbbell', 'Set up an incline bench at a 45-degree angle. Sit on the bench with a dumbbell in each hand, palms facing each other. Plant your feet firmly on the ground and keep your back straight against the bench. Start with the dumbbells at shoulder level, elbows bent and palms facing each other. Press the dumbbells up and away from your body, extending your arms fully. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Planta los pies firmemente en el suelo y mantén la espalda recta contra el banco. Comienza con las mancuernas a la altura de los hombros, con los codos flexionados y las palmas enfrentadas entre sí. Empuja las mancuernas hacia arriba y alejándolas del cuerpo, extendiendo completamente los brazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0324-OVLmUuL.jpg', 'videos/0324-OVLmUuL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1283', 'dumbbell incline press on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball with a dumbbell in each hand, palms facing forward. Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball. Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides. Press the dumbbells upward, extending your arms fully. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas hacia adelante. Camina lentamente con los pies hacia adelante, bajando el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados. Empuja las mancuernas hacia arriba, extendiendo completamente los brazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1283-bfiHMpI.jpg', 'videos/1283-bfiHMpI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0325', 'dumbbell incline raise', 'shoulders', 'shoulders', 'dumbbell', 'Sit on an incline bench with a dumbbell in each hand, resting on your thighs. Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward. Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms. Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height. Repeat for the desired number of repetitions.', 'Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate en el banco y levanta las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Manteniendo la espalda contra el banco, exhala y levanta las mancuernas por encima de la cabeza, extendiendo completamente los brazos. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","triceps"]'::jsonb, 'delts', 'images/0325-nxW6BkN.jpg', 'videos/0325-nxW6BkN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0326', 'dumbbell incline rear lateral raise', 'shoulders', 'shoulders', 'dumbbell', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your chest against the backrest and hold a dumbbell in each hand. Extend your arms straight down with your palms facing each other. Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con el pecho contra el respaldo y sostén una mancuerna en cada mano. Extiende los brazos rectos hacia abajo con las palmas enfrentadas entre sí. Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","rhomboids"]'::jsonb, 'delts', 'images/0326-vYk8lqw.jpg', 'videos/0326-vYk8lqw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0327', 'dumbbell incline row', 'back', 'back', 'dumbbell', 'Set up an incline bench at a 45-degree angle. Grab a dumbbell in each hand and sit on the bench with your chest against the incline. Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders. Pull the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Toma una mancuerna en cada mano y siéntate en el banco con el pecho apoyado contra la inclinación. Extiende completamente los brazos, dejando que las mancuernas cuelguen rectas hacia abajo desde los hombros. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/0327-7vG5o25.jpg', 'videos/0327-7vG5o25.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0328', 'dumbbell incline shoulder raise', 'chest', 'chest', 'dumbbell', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down. Rest the dumbbells on your thighs and lean back onto the bench. Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward. Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows. Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height. Repeat for the desired number of repetitions.', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia abajo. Apoya las mancuernas sobre los muslos y recuéstate en el banco. Usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia adelante. Exhala y levanta lentamente las mancuernas por encima de la cabeza, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","trapezius"]'::jsonb, 'serratus anterior', 'images/0328-6e2DcYX.jpg', 'videos/0328-6e2DcYX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0329', 'dumbbell incline shrug', 'back', 'back', 'dumbbell', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand. Place your feet flat on the ground and let your arms hang straight down with your palms facing your body. Keeping your arms straight, shrug your shoulders up towards your ears as high as possible. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano. Coloca los pies planos sobre el suelo y deja que los brazos cuelguen rectos hacia abajo con las palmas hacia el cuerpo. Manteniendo los brazos rectos, encoge los hombros hacia las orejas lo más alto posible. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'traps', 'images/0329-JymLInS.jpg', 'videos/0329-JymLInS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3542', 'dumbbell incline t-raise', 'shoulders', 'shoulders', 'dumbbell', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards. Lean forward and let your arms hang straight down, perpendicular to the floor. Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a ''T'' shape with your body. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro. Inclínate hacia adelante y deja que los brazos cuelguen rectos hacia abajo, perpendiculares al suelo. Manteniendo los brazos rectos, levántalos hacia los lados hasta que queden paralelos al suelo, formando una ''T'' con el cuerpo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","rhomboids"]'::jsonb, 'delts', 'images/3542-jgbvVJ0.jpg', 'videos/3542-jgbvVJ0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0330', 'dumbbell incline triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an incline bench with a dumbbell in each hand, palms facing inwards. Extend your arms fully overhead, keeping your elbows close to your head. Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary. Pause for a moment, then raise the dumbbells back to the starting position by extending your arms. Repeat for the desired number of repetitions.', 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adentro. Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza. Baja las mancuernas detrás de la cabeza flexionando los codos, manteniendo los brazos superiores quietos. Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0330-OVIKwsd.jpg', 'videos/0330-OVIKwsd.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0331', 'dumbbell incline twisted flyes', 'chest', 'chest', 'dumbbell', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other. Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement. Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top. Repeat for the desired number of repetitions.', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho, con los brazos extendidos. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento. Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0331-1PLE8e9.jpg', 'videos/0331-1PLE8e9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1733', 'dumbbell incline two arm extension', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an incline bench with a dumbbell in each hand, resting on your thighs. Slowly lie back on the bench, keeping the dumbbells close to your chest. Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate lentamente en el banco, manteniendo las mancuernas cerca del pecho. Una vez completamente recostado, extiende los brazos rectos hacia el techo, manteniendo los codos ligeramente flexionados. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1733-U7D9Fx3.jpg', 'videos/1733-U7D9Fx3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3541', 'dumbbell incline y-raise', 'back', 'back', 'dumbbell', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards. Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows. Raise your arms out to the sides and up in a Y shape until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro. Inclínate ligeramente hacia adelante y deja que los brazos cuelguen rectos hacia abajo, manteniendo una ligera flexión en los codos. Levanta los brazos hacia los lados y hacia arriba formando una Y hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","rear deltoids"]'::jsonb, 'upper back', 'images/3541-PbzNu7c.jpg', 'videos/3541-PbzNu7c.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0332', 'dumbbell iron cross', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body. Pause for a moment, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, formando una T con el cuerpo. Haz una pausa por un momento, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'delts', 'images/0332-cALkHHX.jpg', 'videos/0332-cALkHHX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0333', 'dumbbell kickback', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle. Extend your arms straight back, squeezing your triceps at the top of the movement. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Acerca los brazos superiores a los costados, con los codos flexionados en un ángulo de 90 grados. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0333-W6PxUkg.jpg', 'videos/0333-W6PxUkg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1734', 'dumbbell kickbacks on exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle. Extend your arms straight back, squeezing your triceps at the top of the movement. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","back"]'::jsonb, 'triceps', 'images/1734-cAvTaSg.jpg', 'videos/1734-cAvTaSg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1660', 'dumbbell kneeling bicep curl exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Kneel on the floor with an exercise ball in front of you. Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up. Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Arrodíllate en el suelo con un balón de estabilidad frente a ti. Coloca los codos sobre el balón de estabilidad, sosteniendo una mancuerna en cada mano con las palmas hacia arriba. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1660-2JCuFTU.jpg', 'videos/1660-2JCuFTU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0334', 'dumbbell lateral raise', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Keep your back straight and engage your core. Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps"]'::jsonb, 'delts', 'images/0334-DsgkuIt.jpg', 'videos/0334-DsgkuIt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0335', 'dumbbell lateral to front raise', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body. Keep your back straight and engage your core. Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Luego, levanta los brazos frente a ti hasta que queden paralelos al suelo, manteniendo nuevamente una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","biceps"]'::jsonb, 'delts', 'images/0335-xMjBKwn.jpg', 'videos/0335-xMjBKwn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0336', 'dumbbell lunge', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step forward with your right foot, lowering your body into a lunge position. Keep your back straight and your chest up as you lower your body. Push through your right heel to return to the starting position. Repeat with your left leg. Alternate legs for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mantén la espalda recta y el pecho erguido mientras bajas el cuerpo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda. Alterna las piernas el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0336-RRWFUcw.jpg', 'videos/0336-RRWFUcw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1658', 'dumbbell lunge with bicep curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward. Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground. As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body. Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides. Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. La rodilla derecha debe quedar flexionada en un ángulo de 90 grados y la rodilla izquierda debe quedar justo por encima del suelo. Mientras avanzas en la zancada, flexiona simultáneamente las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la parte baja de la zancada, luego empuja con el talón derecho para volver a la posición inicial, bajando las mancuernas de nuevo a los costados. Repite la zancada y el curl de bíceps en el lado opuesto, dando un paso adelante con el pie izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings"]'::jsonb, 'biceps', 'images/1658-Mz6lLcW.jpg', 'videos/1658-Mz6lLcW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0337', 'dumbbell lying extension (across face)', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other. Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground. Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho, con las palmas enfrentadas entre sí. Manteniendo los brazos superiores quietos, baja lentamente la mancuerna describiendo un arco detrás de la cabeza hasta que los antebrazos queden paralelos al suelo. Haz una pausa por un momento, luego contrae los tríceps para llevar la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0337-L2V5Nan.jpg', 'videos/0337-L2V5Nan.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1729', 'dumbbell lying alternate extension', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other. Extend your arms straight up over your chest, keeping a slight bend in your elbows. Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended. Pause for a moment at the bottom, then raise the dumbbell back up to the starting position. Repeat with the other arm, alternating sides for the desired number of repetitions.', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Baja una mancuerna hacia la cabeza, flexionando el codo, mientras mantienes el otro brazo extendido. Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial. Repite con el otro brazo, alternando lados el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1729-NfP83rA.jpg', 'videos/1729-NfP83rA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0338', 'dumbbell lying elbow press', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest. Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary. Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho. Baja las mancuernas hacia los hombros flexionando los codos, manteniendo los brazos superiores quietos. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial extendiendo los codos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0338-eOCOwIR.jpg', 'videos/0338-eOCOwIR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0863', 'dumbbell lying external shoulder rotation', 'shoulders', 'shoulders', 'dumbbell', 'Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees. Hold a dumbbell in your hand with your palm facing down. Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible. Pause for a moment at the top, then slowly lower your forearm back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Túmbate de lado en un banco plano con el brazo superior contra el costado y el codo flexionado a 90 grados. Sostén una mancuerna en la mano con la palma hacia abajo. Manteniendo el brazo superior contra el costado, gira lentamente el antebrazo hacia arriba lo más posible. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'rotator cuff', '["rotator cuff","triceps"]'::jsonb, 'delts', 'images/0863-bmBf7LN.jpg', 'videos/0863-bmBf7LN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0339', 'dumbbell lying femoral', 'upper legs', 'upper legs', 'dumbbell', 'Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen. Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba con las piernas extendidas y una mancuerna apoyada sobre el abdomen bajo. Flexiona las rodillas y lleva la mancuerna hacia los glúteos, manteniendo los pies apoyados en el suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes"]'::jsonb, 'hamstrings', 'images/0339-FkBIE6a.jpg', 'videos/0339-FkBIE6a.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0340', 'dumbbell lying hammer press', 'chest', 'chest', 'dumbbell', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up. Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle. Press the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba. Baja las mancuernas a los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0340-7gdLIXa.jpg', 'videos/0340-7gdLIXa.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2470', 'dumbbell lying on floor rear delt raise', 'shoulders', 'shoulders', 'dumbbell', 'Lie face down on the floor with a dumbbell in each hand, palms facing each other. Extend your arms straight out in front of you, keeping a slight bend in your elbows. Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo en el suelo con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos frente a ti, manteniendo una ligera flexión en los codos. Activando los músculos de los hombros, levanta los brazos hacia arriba y hacia los lados, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/2470-Ion0XWz.jpg', 'videos/2470-Ion0XWz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0341', 'dumbbell lying one arm deltoid rear', 'shoulders', 'shoulders', 'dumbbell', 'Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards. Extend your arm straight down towards the floor, keeping it close to your body. Raise your arm up and back, squeezing your shoulder blade towards your spine. Pause for a moment at the top, then slowly lower your arm back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia adentro. Extiende el brazo recto hacia el suelo, manteniéndolo cerca del cuerpo. Levanta el brazo hacia arriba y hacia atrás, acercando el omóplato hacia la columna. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/0341-gSw59a4.jpg', 'videos/0341-gSw59a4.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0343', 'dumbbell lying one arm press', 'chest', 'chest', 'dumbbell', 'Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground. Hold the dumbbell at shoulder level with your palm facing forward. Press the dumbbell upward until your arm is fully extended. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Túmbate boca arriba en un banco con una mancuerna en una mano y los pies apoyados en el suelo. Sostén la mancuerna a la altura del hombro con la palma hacia adelante. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0343-zGSIWQi.jpg', 'videos/0343-zGSIWQi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0342', 'dumbbell lying one arm press v. 2', 'chest', 'chest', 'dumbbell', 'Lie flat on a bench with your back supported and feet flat on the ground. Hold a dumbbell in one hand with your palm facing towards your feet. Extend your arm straight up towards the ceiling, keeping your elbow slightly bent. Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body. Pause for a moment at the bottom, then push the dumbbell back up to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Túmbate boca arriba en un banco con la espalda apoyada y los pies planos sobre el suelo. Sostén una mancuerna en una mano con la palma hacia los pies. Extiende el brazo recto hacia el techo, manteniendo el codo ligeramente flexionado. Baja lentamente la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0342-K3dIO25.jpg', 'videos/0342-K3dIO25.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0344', 'dumbbell lying one arm pronated triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with your back and head supported, and your feet flat on the ground. Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder. Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow. Pause for a moment at the bottom, then extend your arm back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo. Sostén una mancuerna en una mano con la palma hacia abajo, y extiende el brazo recto por encima del hombro. Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo. Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0344-wyaqzOS.jpg', 'videos/0344-wyaqzOS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0345', 'dumbbell lying one arm rear lateral raise', 'shoulders', 'shoulders', 'dumbbell', 'Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor. Keep your arm straight and lift the dumbbell out to the side, away from your body. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, colgando hacia el suelo. Mantén el brazo recto y levanta la mancuerna hacia el lado, alejándola del cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'traps', '["traps","rhomboids"]'::jsonb, 'delts', 'images/0345-KwFGiEP.jpg', 'videos/0345-KwFGiEP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0346', 'dumbbell lying one arm supinated triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with your back and head supported, and your feet flat on the ground. Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder. Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow. Pause for a moment at the bottom, then extend your arm back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo. Sostén una mancuerna en una mano con agarre supino, y extiende el brazo recto por encima del hombro. Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo. Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'triceps', 'images/0346-zZlORz6.jpg', 'videos/0346-zZlORz6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0347', 'dumbbell lying pronation', 'lower arms', 'lower arms', 'dumbbell', 'Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand. Rotate your palms so they are facing up. Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down. Inhale and slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo en un banco con el pecho hacia abajo y los brazos extendidos rectos hacia abajo, sosteniendo una mancuerna en cada mano. Gira las palmas de modo que queden mirando hacia arriba. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas mientras giras las palmas hacia abajo. Inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'forearms', 'images/0347-mym4hJo.jpg', 'videos/0347-mym4hJo.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2705', 'dumbbell lying pronation on floor', 'lower arms', 'lower arms', 'dumbbell', 'Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand. Rotate your palms so they are facing down towards the floor. Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms. Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level. Hold for a moment, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo en el suelo con los brazos extendidos rectos frente a ti, sosteniendo una mancuerna en cada mano. Gira las palmas de modo que queden mirando hacia el suelo. Manteniendo los brazos rectos, levanta las mancuernas del suelo contrayendo los antebrazos. Continúa levantando hasta que los antebrazos estén completamente contraídos y las mancuernas queden a la altura de los hombros. Mantén la posición por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps"]'::jsonb, 'forearms', 'images/2705-7RWNjiB.jpg', 'videos/2705-7RWNjiB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1284', 'dumbbell lying pullover on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball and roll forward until your upper back is resting on the ball. Hold a dumbbell with both hands and extend your arms straight up over your chest. Slowly lower the dumbbell behind your head while keeping your arms straight. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el balón. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho. Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","back"]'::jsonb, 'pectorals', 'images/1284-iK59oEA.jpg', 'videos/1284-iK59oEA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1328', 'dumbbell lying rear delt row', 'back', 'back', 'dumbbell', 'Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards. Extend your arms straight down towards the floor, keeping a slight bend in your elbows. Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas hacia adentro. Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos. Activando los músculos de la espalda, levanta las mancuernas hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","biceps"]'::jsonb, 'upper back', 'images/1328-XUUD0Fs.jpg', 'videos/1328-XUUD0Fs.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0348', 'dumbbell lying rear lateral raise', 'shoulders', 'shoulders', 'dumbbell', 'Lie face down on a flat bench with a dumbbell in each hand, palms facing each other. Extend your arms straight down towards the floor, keeping a slight bend in your elbows. Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos. Activando los músculos de los hombros, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","rhomboids"]'::jsonb, 'delts', 'images/0348-53Ttlck.jpg', 'videos/0348-53Ttlck.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1735', 'dumbbell lying single extension', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest. Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary. Pause briefly at the bottom of the movement, then extend your arm back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Túmbate boca arriba en un banco con una mancuerna en una mano y el brazo completamente extendido por encima del pecho. Baja la mancuerna de manera controlada hacia la frente, manteniendo el brazo superior quieto. Haz una breve pausa en la parte inferior del movimiento, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1735-6MfS53i.jpg', 'videos/1735-6MfS53i.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0349', 'dumbbell lying supination', 'lower arms', 'lower arms', 'dumbbell', 'Lie flat on a bench with your feet flat on the ground. Hold a dumbbell in each hand with your palms facing up and your arms fully extended. Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, flexiona las mancuernas hacia los hombros contrayendo los antebrazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'forearms', 'images/0349-M2Pm3zj.jpg', 'videos/0349-M2Pm3zj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2706', 'dumbbell lying supination on floor', 'lower arms', 'lower arms', 'dumbbell', 'Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand. Rotate your palms to face up, keeping your elbows close to your sides. Slowly curl the dumbbells towards your shoulders, squeezing your forearms. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en el suelo con las piernas extendidas y los brazos a los costados, sosteniendo una mancuerna en cada mano. Gira las palmas hacia arriba, manteniendo los codos cerca de los costados. Flexiona lentamente las mancuernas hacia los hombros, contrayendo los antebrazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'forearms', 'images/2706-rEhi2o5.jpg', 'videos/2706-rEhi2o5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1661', 'dumbbell lying supine biceps curl', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with your back and head supported, and your feet flat on the ground. Hold a dumbbell in each hand with your palms facing up and your arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1661-XVzF3iZ.jpg', 'videos/1661-XVzF3iZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0350', 'dumbbell lying supine curl', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0350-KUaZst7.jpg', 'videos/0350-KUaZst7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0351', 'dumbbell lying triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other. Extend your arms straight up over your chest, keeping your elbows close to your body. Lower the dumbbells down towards your forehead, bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, manteniendo los codos cerca del cuerpo. Baja las mancuernas hacia la frente, flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0351-mpKZGWz.jpg', 'videos/0351-mpKZGWz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1662', 'dumbbell lying wide curl', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1662-qm9veZw.jpg', 'videos/1662-qm9veZw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0352', 'dumbbell neutral grip bench press', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest. Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body. Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sostén una mancuerna en cada mano con agarre neutro (palmas enfrentadas entre sí) y los brazos extendidos rectos hacia arriba sobre el pecho. Baja lentamente las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0352-pP8wP2P.jpg', 'videos/0352-pP8wP2P.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1285', 'dumbbell one arm bench fly', 'chest', 'chest', 'dumbbell', 'Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh. Lie back on the bench, keeping the dumbbell pressed against your thigh. Using your free hand, help lift the dumbbell up to the starting position. Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward. Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow. Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms and repeat.', 'Siéntate en un banco plano con una mancuerna en una mano, apoyándola sobre el muslo. Recuéstate en el banco, manteniendo la mancuerna presionada contra el muslo. Usando la mano libre, ayuda a levantar la mancuerna hasta la posición inicial. Sostén la mancuerna directamente sobre el hombro con el brazo extendido y la palma hacia adentro. Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo. Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento y lleva la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo y repite.', 'shoulders', '["shoulders"]'::jsonb, 'pectorals', 'images/1285-o5Jsk92.jpg', 'videos/1285-o5Jsk92.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0292', 'dumbbell one arm bent-over row', 'back', 'back', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body. Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged. Let the dumbbell hang straight down towards the floor, with your arm fully extended. Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Deja que la mancuerna cuelgue recta hacia el suelo, con el brazo completamente extendido. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0292-C0MA9bC.jpg', 'videos/0292-C0MA9bC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1286', 'dumbbell one arm chest fly on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground. Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball. Extend your arm with the dumbbell straight up above your chest, palm facing inward. Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow. Pause for a moment when your arm is parallel to the ground. Engage your chest muscles to bring the dumbbell back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo. Camina con los pies hacia adelante, haciendo rodar el balón hasta que la parte superior de la espalda quede apoyada en el balón y la cabeza, el cuello y los hombros queden fuera de él. Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro. Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo. Haz una pausa por un momento cuando el brazo esté paralelo al suelo. Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1286-Bpkf41o.jpg', 'videos/1286-Bpkf41o.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0353', 'dumbbell one arm concentration curl (on stability ball)', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor. Rest your elbow on the inside of your thigh, just above the knee. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps. Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms and repeat.', 'Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna en una mano con la palma hacia arriba y el brazo extendido hacia el suelo. Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa por un momento en la parte superior del movimiento, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo y repite.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0353-k5IpyHg.jpg', 'videos/0353-k5IpyHg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1287', 'dumbbell one arm decline chest press', 'chest', 'chest', 'dumbbell', 'Lie on a decline bench with a dumbbell in one hand, resting on your chest. Place your feet flat on the ground and keep your back pressed against the bench. Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho. Coloca los pies planos sobre el suelo y mantén la espalda presionada contra el banco. Extiende el brazo y empuja la mancuerna hacia el techo, extendiendo completamente el codo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1287-REGM1dE.jpg', 'videos/1287-REGM1dE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1288', 'dumbbell one arm fly on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground. Walk your feet forward and roll your body down until your upper back is resting on the exercise ball. Extend your arm with the dumbbell straight up above your chest, palm facing inwards. Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow. Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la parte superior de la espalda quede apoyada sobre el balón de estabilidad. Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro. Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1288-Am02iPd.jpg', 'videos/1288-Am02iPd.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1736', 'dumbbell one arm french press on exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle. Extend your arm straight up towards the ceiling, keeping your elbow stationary. Slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia arriba y el codo flexionado en un ángulo de 90 grados. Extiende el brazo recto hacia el techo, manteniendo el codo quieto. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1736-ziFKQXP.jpg', 'videos/1736-ziFKQXP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1663', 'dumbbell one arm hammer preacher curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad. Hold the dumbbell with a neutral grip (palms facing your body). Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco scott con una mancuerna en una mano y el brazo superior apoyado sobre la almohadilla. Sostén la mancuerna con agarre neutro (palmas hacia el cuerpo). Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1663-4dF3maG.jpg', 'videos/1663-4dF3maG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1621', 'dumbbell one arm hammer press on exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle. Place your other hand on your hip for stability. Press the dumbbell upwards, extending your arm fully. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados. Coloca la otra mano en la cadera para mantener el equilibrio. Empuja la mancuerna hacia arriba, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders","chest"]'::jsonb, 'triceps', 'images/1621-VYmYxK5.jpg', 'videos/1621-VYmYxK5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1289', 'dumbbell one arm incline chest press', 'chest', 'chest', 'dumbbell', 'Adjust the incline bench to a 45-degree angle. Sit on the bench with your back against the pad and feet flat on the ground. Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder. Push the dumbbell up and away from your body, extending your arm fully. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ajusta el banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo. Sostén una mancuerna en una mano con agarre prono, apoyándola sobre el hombro. Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1289-PDaMuyV.jpg', 'videos/1289-PDaMuyV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0354', 'dumbbell one arm kickback', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in your right hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Bring your right elbow up to your side, keeping it bent at a 90-degree angle. Extend your right arm straight back, squeezing your triceps at the top of the movement. Slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados. Extiende el brazo derecho recto hacia atrás, contrayendo el tríceps en la parte superior del movimiento. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0354-bQy2Eni.jpg', 'videos/0354-bQy2Eni.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0355', 'dumbbell one arm lateral raise', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body. Keep your back straight and your core engaged throughout the exercise. Raise the dumbbell to the side, keeping your arm straight and your palm facing down. Continue lifting until your arm is parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo. Mantén la espalda recta y el core activado durante todo el ejercicio. Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'trapezius', '["trapezius","triceps"]'::jsonb, 'delts', 'images/0355-n5cWCsI.jpg', 'videos/0355-n5cWCsI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0356', 'dumbbell one arm lateral raise with support', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body. Place your other hand on a stable surface, such as a bench or wall, for support. Keep your back straight and engage your core. Raise the dumbbell out to the side, keeping your arm straight and your palm facing down. Continue lifting until your arm is parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano, con la palma hacia el cuerpo. Coloca la otra mano sobre una superficie estable, como un banco o una pared, para apoyarte. Mantén la espalda recta y activa el core. Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'trapezius', '["trapezius","rotator cuff"]'::jsonb, 'delts', 'images/0356-Yg7MJAT.jpg', 'videos/0356-Yg7MJAT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1290', 'dumbbell one arm press on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward. Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna en una mano y colócala a la altura del hombro, con el codo flexionado y la palma hacia adelante. Empuja lentamente la mancuerna hacia arriba hasta que el brazo quede completamente extendido, manteniendo el core activado y el equilibrio sobre el balón de estabilidad. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'shoulders', '["shoulders","triceps","core"]'::jsonb, 'pectorals', 'images/1290-QZFv5ui.jpg', 'videos/1290-QZFv5ui.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1665', 'dumbbell one arm prone curl', 'upper arms', 'upper arms', 'dumbbell', 'Lie face down on a flat bench with a dumbbell in one hand, palm facing down. Extend your arm fully, letting it hang straight down towards the floor. Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia abajo. Extiende completamente el brazo, dejando que cuelgue recto hacia el suelo. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1665-JWjujiY.jpg', 'videos/1665-JWjujiY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1666', 'dumbbell one arm prone hammer curl', 'upper arms', 'upper arms', 'dumbbell', 'Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended. Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo y el brazo completamente extendido. Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1666-LIGZSTA.jpg', 'videos/1666-LIGZSTA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1291', 'dumbbell one arm pullover on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a dumbbell with one hand and extend your arm straight up above your chest. Slowly lower the dumbbell behind your head while keeping your arm straight. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna con una mano y extiende el brazo recto hacia arriba sobre el pecho. Baja lentamente la mancuerna detrás de la cabeza manteniendo el brazo recto. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'triceps', '["triceps","latissimus dorsi","rhomboids"]'::jsonb, 'pectorals', 'images/1291-bQHPBU3.jpg', 'videos/1291-bQHPBU3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0358', 'dumbbell one arm reverse wrist curl', 'lower arms', 'lower arms', 'dumbbell', 'Sit on a bench or chair with your feet flat on the ground. Hold a dumbbell in one hand with an overhand grip, palm facing down. Rest your forearm on your thigh, with your wrist hanging off the edge. Slowly lower the dumbbell towards the ground by flexing your wrist. Pause for a moment at the bottom, then slowly curl your wrist back up towards your body. Repeat for the desired number of repetitions, then switch to the other arm.', 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sostén una mancuerna en una mano con agarre prono, con la palma hacia abajo. Apoya el antebrazo sobre el muslo, con la muñeca colgando fuera del borde. Baja lentamente la mancuerna hacia el suelo flexionando la muñeca. Haz una pausa por un momento en la parte inferior, luego flexiona lentamente la muñeca de vuelta hacia el cuerpo. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'wrist extensors', '["wrist extensors"]'::jsonb, 'forearms', 'images/0358-BwSNDGt.jpg', 'videos/0358-BwSNDGt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0359', 'dumbbell one arm reverse fly (with support)', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing inwards. Lean forward and place your free hand on the bench for support. Keep your arm slightly bent and raise it out to the side until it is parallel to the ground. Pause for a moment at the top, then slowly lower your arm back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia adentro. Inclínate hacia adelante y coloca la mano libre sobre el banco para apoyarte. Mantén el brazo ligeramente flexionado y levántalo hacia el lado hasta que quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/0359-e25F58f.jpg', 'videos/0359-e25F58f.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1622', 'dumbbell one arm reverse grip press', 'chest', 'chest', 'dumbbell', 'Sit on a flat bench with a dumbbell in one hand, palm facing towards your body. Place your feet flat on the ground and keep your back straight. Raise the dumbbell to shoulder height, keeping your elbow close to your body. Press the dumbbell upwards until your arm is fully extended. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Siéntate en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo. Coloca los pies planos sobre el suelo y mantén la espalda recta. Levanta la mancuerna hasta la altura del hombro, manteniendo el codo cerca del cuerpo. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1622-Ze7MoIb.jpg', 'videos/1622-Ze7MoIb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1414', 'dumbbell one arm reverse preacher curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip. Lower the dumbbell slowly until your arm is fully extended. Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary. Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco scott con el pecho contra la almohadilla y el brazo extendido sobre el borde del banco, sosteniendo una mancuerna con agarre supino. Baja lentamente la mancuerna hasta que el brazo quede completamente extendido. Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto. Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1414-bWxq4op.jpg', 'videos/1414-bWxq4op.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1667', 'dumbbell one arm reverse spider curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended. Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie con una mancuerna en una mano, con la palma hacia abajo y el brazo completamente extendido. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro flexionando el codo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1667-VdLZ3nB.jpg', 'videos/1667-VdLZ3nB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1668', 'dumbbell one arm seated bicep curl on exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing up and your arm fully extended. Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1668-s999Hdo.jpg', 'videos/1668-s999Hdo.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1669', 'dumbbell one arm seated hammer curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in one hand with a neutral grip (palms facing each other). Rest your elbow on the inside of your thigh, just above the knee. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén una mancuerna en una mano con agarre neutro (palmas enfrentadas entre sí). Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1669-jK2hZ6n.jpg', 'videos/1669-jK2hZ6n.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1415', 'dumbbell one arm seated neutral wrist curl', 'lower arms', 'lower arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up. Rest your forearm on your thigh, allowing your wrist to hang off the edge. Keeping your forearm stationary, curl your wrist upward as far as possible. Pause for a moment at the top, then slowly lower your wrist back down to the starting position. Repeat for the desired number of repetitions, then switch to the other hand.', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba. Apoya el antebrazo sobre el muslo, dejando que la muñeca cuelgue fuera del borde. Manteniendo el antebrazo quieto, flexiona la muñeca hacia arriba lo más posible. Haz una pausa por un momento en la parte superior, luego baja lentamente la muñeca de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia a la otra mano.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/1415-YtaCTYl.jpg', 'videos/1415-YtaCTYl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0361', 'dumbbell one arm shoulder press', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward. Press the dumbbell upward until your arm is fully extended overhead. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0361-84RyJf8.jpg', 'videos/0361-84RyJf8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0360', 'dumbbell one arm shoulder press v. 2', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward. Engage your core and press the dumbbell straight up overhead, fully extending your arm. Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante. Activa el core y empuja la mancuerna directamente hacia arriba por encima de la cabeza, extendiendo completamente el brazo. Haz una pausa por un momento en la parte superior, luego baja lentamente la mancuerna de vuelta a la altura del hombro. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0360-1TkiAFK.jpg', 'videos/0360-1TkiAFK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3888', 'dumbbell one arm snatch', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Lower the dumbbell towards the ground, keeping it close to your body. Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line. As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm. Catch the dumbbell overhead with a slight bend in your knees and hips. Lower the dumbbell back down to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Baja la mancuerna hacia el suelo, manteniéndola cerca del cuerpo. Extiende explosivamente las caderas, las rodillas y los tobillos, impulsando la mancuerna hacia arriba en línea recta. Cuando la mancuerna alcance la altura del hombro, gira rápidamente la mano y empújala por encima de la cabeza, extendiendo completamente el brazo. Recibe la mancuerna por encima de la cabeza con una ligera flexión en las rodillas y las caderas. Baja la mancuerna de nuevo a la posición inicial de manera controlada. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'hamstrings', '["hamstrings","quadriceps","core"]'::jsonb, 'glutes', 'images/3888-6pTkI99.jpg', 'videos/3888-6pTkI99.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1670', 'dumbbell one arm standing curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended. Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie con una mancuerna en una mano, con la palma hacia adelante y el brazo completamente extendido. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia arriba contrayendo el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1670-ffQsyBj.jpg', 'videos/1670-ffQsyBj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1671', 'dumbbell one arm standing hammer curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona las pesas mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1671-2sQGZ5b.jpg', 'videos/1671-2sQGZ5b.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0362', 'dumbbell one arm triceps extension (on bench)', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in one hand and place your other hand on the bench for support. Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward. Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary. Extend your arm back up to the starting position, fully straightening your elbow. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén una mancuerna en una mano y coloca la otra mano sobre el banco para apoyarte. Levanta la mancuerna por encima de la cabeza, manteniendo el brazo superior cerca de la cabeza y el codo apuntando hacia adelante. Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto. Extiende el brazo de vuelta a la posición inicial, estirando completamente el codo. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0362-nAuHPcD.jpg', 'videos/0362-nAuHPcD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0363', 'dumbbell one arm upright row', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip. Let the dumbbell hang at arm''s length in front of your thighs, with your palm facing your body. Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow. Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono. Deja que la mancuerna cuelgue a la distancia de un brazo frente a los muslos, con la palma hacia el cuerpo. Manteniendo la espalda recta y el core activado, exhala y levanta la mancuerna recta hacia la barbilla, guiando con el codo. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'traps', '["traps","biceps"]'::jsonb, 'delts', 'images/0363-6cKQC5E.jpg', 'videos/0363-6cKQC5E.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0364', 'dumbbell one arm wrist curl', 'lower arms', 'lower arms', 'dumbbell', 'Sit on a bench or chair with your feet flat on the ground. Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh. Allow your wrist to extend, letting the dumbbell roll down towards your fingers. Slowly curl your wrist back up, bringing the dumbbell towards your forearm. Repeat for the desired number of repetitions, then switch to the other hand.', 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo. Permite que la muñeca se extienda, dejando que la mancuerna ruede hacia los dedos. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Repite el número de repeticiones deseado, luego cambia a la otra mano.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/0364-q8aHNoF.jpg', 'videos/0364-q8aHNoF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1672', 'dumbbell one arm zottman preacher curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip. Rest your upper arm on the preacher bench pad, allowing your arm to fully extend. Curl the dumbbell up towards your shoulder, keeping your upper arm stationary. At the top of the curl, rotate your wrist so that your palm faces up. Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco scott y sostén una mancuerna en una mano con agarre supino. Apoya el brazo superior sobre la almohadilla del banco scott, permitiendo que el brazo se extienda completamente. Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto. En la parte superior del curl, gira la muñeca de modo que la palma quede hacia arriba. Baja lentamente la mancuerna de vuelta a la posición inicial, girando la muñeca de regreso a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1672-sxY5Biu.jpg', 'videos/1672-sxY5Biu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1292', 'dumbbell one leg fly on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball with a dumbbell in each hand, palms facing each other. Place one foot on the ground and extend the other leg straight out in front of you. Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows. Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest. Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', 'Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Coloca un pie en el suelo y extiende la otra pierna recta hacia adelante. Inclínate ligeramente hacia adelante y lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos. Baja lentamente las mancuernas hacia abajo y hacia los lados, sintiendo un estiramiento en el pecho. Haz una pausa por un momento en la parte inferior, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1292-pH2x2jj.jpg', 'videos/1292-pH2x2jj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0365', 'dumbbell over bench neutral wrist curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up. Rest your forearms on the bench, allowing your wrists to hang off the edge. Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas hacia los hombros. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0365-BKa8dmT.jpg', 'videos/0365-BKa8dmT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0366', 'dumbbell over bench one arm neutral wrist curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up. Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco con una mancuerna en una mano y el brazo extendido sobre el banco, con la palma hacia arriba. Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, manteniendo la muñeca en posición neutra. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0366-IvV6C9M.jpg', 'videos/0366-IvV6C9M.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1441', 'dumbbell over bench one arm reverse wrist curl', 'lower arms', 'lower arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down. Rest your forearm on the bench with your wrist hanging off the edge. Slowly curl your wrist upwards, bringing the dumbbell towards your forearm. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. Apoya el antebrazo en el banco con la muñeca colgando del borde. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/1441-4Jc36XM.jpg', 'videos/1441-4Jc36XM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0367', 'dumbbell over bench one arm wrist curl', 'lower arms', 'lower arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down. Rest your forearm on the bench with your wrist hanging off the edge. Slowly curl your wrist upwards, bringing the dumbbell towards your forearm. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. Apoya el antebrazo en el banco con la muñeca colgando del borde. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'biceps', '["biceps","shoulders"]'::jsonb, 'forearms', 'images/0367-KI1DjNN.jpg', 'videos/0367-KI1DjNN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0368', 'dumbbell over bench revers wrist curl', 'lower arms', 'lower arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down. Rest your forearms on the bench, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the dumbbells towards your body. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas hacia abajo. Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/0368-3tAXPQ6.jpg', 'videos/0368-3tAXPQ6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0369', 'dumbbell over bench wrist curl', 'lower arms', 'lower arms', 'dumbbell', 'Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand. Allow your wrists to hang over the edge of the bench. Slowly curl your wrists upward, squeezing your forearms at the top of the movement. Pause for a moment, then slowly lower your wrists back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los antebrazos apoyados en él y las palmas hacia arriba, sujetando una mancuerna en cada mano. Deja que tus muñecas cuelguen del borde del banco. Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento. Haz una pausa por un momento y luego baja lentamente las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/0369-D1xYJAU.jpg', 'videos/0369-D1xYJAU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1329', 'dumbbell palm rotational bent over row', 'back', 'back', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Bend forward at the hips, keeping your back straight and your knees slightly bent. Let your arms hang straight down, palms facing your body. Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body. As you pull the dumbbells up, rotate your palms so they face away from your body. Squeeze your shoulder blades together at the top of the movement. Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Deja que los brazos cuelguen rectos hacia abajo, con las palmas hacia tu cuerpo. Activa el core y tira de las mancuernas hacia tu pecho, manteniendo los codos cerca del cuerpo. Mientras subes las mancuernas, gira las palmas para que queden mirando hacia afuera, alejadas de tu cuerpo. Junta los omóplatos en la parte superior del movimiento. Baja lentamente las mancuernas hasta la posición inicial, girando las palmas de vuelta a su posición original. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1329-wt6rwjk.jpg', 'videos/1329-wt6rwjk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1623', 'dumbbell palms in incline bench press', 'upper arms', 'upper arms', 'dumbbell', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your back against the backrest and feet flat on the ground. Hold a dumbbell in each hand with an overhand grip, palms facing inwards. Extend your arms straight up above your chest, keeping a slight bend in your elbows. Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body. Pause for a moment at the bottom, then press the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia adentro. Extiende los brazos rectos hacia arriba, por encima del pecho, manteniendo una ligera flexión en los codos. Baja las mancuernas lentamente hacia los hombros, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la posición más baja y luego presiona las mancuernas de vuelta hacia arriba, hasta la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1623-8eqjhOl.jpg', 'videos/1623-8eqjhOl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0370', 'dumbbell peacher hammer curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Then, inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the recommended amount of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0370-F1KxjBa.jpg', 'videos/0370-F1KxjBa.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0371', 'dumbbell plyo squat', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Lower your body into a squat position by bending your knees and pushing your hips back. As you reach the bottom of the squat, explode upward, jumping off the ground. While in the air, quickly switch the position of your feet, landing with your opposite foot forward. Immediately lower your body back into a squat position and repeat the jump, switching your feet again. Continue alternating the position of your feet with each jump for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Cuando llegues al punto más bajo de la sentadilla, impúlsate explosivamente hacia arriba, saltando del suelo. Mientras estás en el aire, cambia rápidamente la posición de los pies, aterrizando con el pie opuesto adelante. Baja inmediatamente el cuerpo de vuelta a la posición de sentadilla y repite el salto, cambiando de nuevo los pies. Continúa alternando la posición de los pies en cada salto durante el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0371-S4pwGlc.jpg', 'videos/0371-S4pwGlc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0372', 'dumbbell preacher curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it. Hold a dumbbell in each hand with your palms facing up and your arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco scott con la parte superior de los brazos apoyada en la almohadilla y el pecho contra ella. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0372-jivWf8n.jpg', 'videos/0372-jivWf8n.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1673', 'dumbbell preacher curl over exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una mancuerna con una mano con agarre supino, apoyando el codo sobre el balón de estabilidad. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1673-hwygydB.jpg', 'videos/1673-hwygydB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1293', 'dumbbell press on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs. Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle. Raise the dumbbells to shoulder height, palms facing forward. Press the dumbbells upward until your arms are fully extended. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad con los pies planos en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad hasta que tu zona lumbar quede apoyada sobre el balón y tus rodillas formen un ángulo de 90 grados. Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1293-O8o7q4d.jpg', 'videos/1293-O8o7q4d.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0373', 'dumbbell pronate-grip triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench or chair with your back straight and feet flat on the ground. Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead. Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo. Sujeta una mancuerna con ambas manos, con las palmas hacia abajo, y extiende los brazos rectos por encima de la cabeza. Manteniendo la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante, baja lentamente la mancuerna detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'triceps', 'images/0373-bpJL2Qs.jpg', 'videos/0373-bpJL2Qs.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0374', 'dumbbell prone incline curl', 'upper arms', 'upper arms', 'dumbbell', 'Adjust the bench to a 45-degree incline. Lie face down on the bench with your chest and stomach resting against it. Hold a dumbbell in each hand with your palms facing down and your arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta el banco a una inclinación de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él. Sujeta una mancuerna en cada mano con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0374-mwpPcr1.jpg', 'videos/0374-mwpPcr1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1674', 'dumbbell prone incline hammer curl', 'upper arms', 'upper arms', 'dumbbell', 'Adjust the bench to a 45-degree incline. Lie face down on the bench with a dumbbell in each hand, palms facing each other. Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta el banco a una inclinación de 45 grados. Túmbate boca abajo en el banco con una mancuerna en cada mano, con las palmas mirándose entre sí. Deja que los brazos cuelguen rectos hacia el suelo, manteniendo los codos ligeramente flexionados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1674-cWemPG8.jpg', 'videos/1674-cWemPG8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0375', 'dumbbell pullover', 'chest', 'chest', 'dumbbell', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold a dumbbell with both hands and extend your arms straight above your chest. Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo una ligera flexión en los codos, baja lentamente la mancuerna detrás de la cabeza hasta sentir un estiramiento en el pecho y los hombros. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'latissimus dorsi', '["latissimus dorsi","triceps"]'::jsonb, 'pectorals', 'images/0375-9XjtHvS.jpg', 'videos/0375-9XjtHvS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1294', 'dumbbell pullover hip extension on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs. Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball. Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows. Lower the dumbbell behind your head, keeping your arms straight and maintaining control. Pause for a moment, then raise the dumbbell back to the starting position. While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core. Lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad con los pies planos en el suelo y la mancuerna apoyada sobre los muslos. Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad por tu espalda hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sujeta la mancuerna con ambas manos y extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos. Baja la mancuerna detrás de la cabeza, manteniendo los brazos rectos y con control total. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Manteniendo los brazos extendidos, levanta las caderas del suelo, apretando los glúteos y activando el core. Baja las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/1294-lI7easp.jpg', 'videos/1294-lI7easp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1295', 'dumbbell pullover on exercise ball', 'chest', 'chest', 'dumbbell', 'Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended. Slowly lower the dumbbell behind your head while keeping your arms straight. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad y sujeta una mancuerna con ambas manos por encima del pecho, con los brazos extendidos. Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","latissimus dorsi"]'::jsonb, 'pectorals', 'images/1295-FSD6PGL.jpg', 'videos/1295-FSD6PGL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1700', 'dumbbell push press', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level. Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead. Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros. Flexiona ligeramente las rodillas y baja el cuerpo, luego extiende las piernas de forma explosiva y presiona las mancuernas por encima de la cabeza. Bloquea los brazos en la parte superior del movimiento, luego baja las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/1700-FS63wTN.jpg', 'videos/1700-FS63wTN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0376', 'dumbbell raise', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Keep your back straight and engage your core. Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","rhomboids"]'::jsonb, 'delts', 'images/0376-c9MnDRp.jpg', 'videos/0376-c9MnDRp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2292', 'dumbbell rear delt raise', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/2292-mu5Guxt.jpg', 'videos/2292-mu5Guxt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0377', 'dumbbell rear delt row_shoulder', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold a dumbbell in each hand with your palms facing your body. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arms straight down towards the floor, with a slight bend in your elbows. Raise the dumbbells out to the sides, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende los brazos rectos hacia el suelo, con una ligera flexión en los codos. Levanta las mancuernas hacia los lados, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/0377-EKXOMEh.jpg', 'videos/0377-EKXOMEh.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0378', 'dumbbell rear fly', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms straight down towards the ground, palms facing each other. Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia el suelo, con las palmas mirándose entre sí. Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados y aprieta los omóplatos entre sí. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/0378-8DiFDVA.jpg', 'videos/0378-8DiFDVA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0380', 'dumbbell rear lateral raise', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","rhomboids"]'::jsonb, 'delts', 'images/0380-v1qBec9.jpg', 'videos/0380-v1qBec9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0379', 'dumbbell rear lateral raise (support head)', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","rhomboids"]'::jsonb, 'delts', 'images/0379-UzkLrem.jpg', 'videos/0379-UzkLrem.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0381', 'dumbbell rear lunge', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step backward with your right foot, lowering your body into a lunge position. Bend your left knee and lower your body until your left thigh is parallel to the ground. Pause for a moment, then push through your left heel to return to the starting position. Repeat on the other side, stepping back with your left foot.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso hacia atrás con el pie derecho, bajando el cuerpo a una posición de zancada. Flexiona la rodilla izquierda y baja el cuerpo hasta que el muslo izquierdo quede paralelo al suelo. Haz una pausa por un momento, luego empuja con el talón izquierdo para volver a la posición inicial. Repite del otro lado, dando un paso hacia atrás con el pie izquierdo.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0381-SSsBDwB.jpg', 'videos/0381-SSsBDwB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0382', 'dumbbell revers grip biceps curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0382-e4ojVhP.jpg', 'videos/0382-e4ojVhP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1624', 'dumbbell reverse bench press', 'chest', 'chest', 'dumbbell', 'Lie flat on a bench with your feet flat on the ground and your knees bent. Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet. Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows. Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides. Pause for a moment at the bottom, then push the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con los pies apoyados en el suelo y las rodillas flexionadas. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tus pies. Extiende los brazos rectos hacia el techo, manteniendo una ligera flexión en los codos. Baja lentamente las mancuernas hacia el pecho, permitiendo que los codos se abran hacia los lados. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1624-UIbGx6H.jpg', 'videos/1624-UIbGx6H.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0383', 'dumbbell reverse fly', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms straight down in front of you, palms facing each other. Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí. Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/0383-EAs3xL9.jpg', 'videos/0383-EAs3xL9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1330', 'dumbbell reverse grip incline bench one arm row', 'back', 'back', 'dumbbell', 'Set up an incline bench at a 45-degree angle. Place a dumbbell on the floor next to the bench. Stand facing the bench with your feet shoulder-width apart. Bend at the waist and place your left knee and left hand on the bench for support. Pick up the dumbbell with your right hand using a reverse grip (palm facing down). Keep your back straight and your core engaged. Pull the dumbbell up towards your chest, keeping your elbow close to your body. Squeeze your back muscles at the top of the movement. Lower the dumbbell back down to the starting position in a controlled manner. Repeat for the desired number of repetitions. Switch sides and repeat the exercise with your left arm.', 'Coloca un banco inclinado a un ángulo de 45 grados. Coloca una mancuerna en el suelo junto al banco. Ponte de pie frente al banco con los pies separados a la altura de los hombros. Inclínate desde la cintura y coloca la rodilla izquierda y la mano izquierda sobre el banco para apoyarte. Toma la mancuerna con la mano derecha usando un agarre inverso (con la palma hacia abajo). Mantén la espalda recta y el core activado. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo. Aprieta los músculos de la espalda en la parte superior del movimiento. Baja la mancuerna de nuevo a la posición inicial de manera controlada. Repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el brazo izquierdo.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/1330-ZIViNh1.jpg', 'videos/1330-ZIViNh1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1331', 'dumbbell reverse grip incline bench two arm row', 'back', 'back', 'dumbbell', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your chest against the backrest and your feet flat on the ground. Hold a dumbbell in each hand with an underhand grip. Lean forward and let your arms hang straight down, fully extended. Pull the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con el pecho apoyado en el respaldo y los pies planos en el suelo. Sujeta una mancuerna en cada mano con agarre supino. Inclínate hacia adelante y deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1331-9pQSkH8.jpg', 'videos/1331-9pQSkH8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2327', 'dumbbell reverse grip row (female)', 'back', 'back', 'dumbbell', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold a dumbbell in each hand with an overhand grip, palms facing your body. Bend forward at the waist, keeping your back straight and your core engaged. Let your arms hang straight down, fully extended, with a slight bend in your elbows. Pull the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tu cuerpo. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos, con una ligera flexión en los codos. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/2327-Nh3mvOO.jpg', 'videos/2327-Nh3mvOO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0384', 'dumbbell reverse preacher curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a preacher bench with your upper arms resting on the pad and your chest against the support. Hold a dumbbell in each hand with an underhand grip, palms facing up. Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps. Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte. Sujeta una mancuerna en cada mano con agarre supino, con las palmas hacia arriba. Manteniendo la parte superior de los brazos fija, exhala y flexiona las mancuernas mientras contraes los bíceps. Continúa flexionando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0384-O8Aq69u.jpg', 'videos/0384-O8Aq69u.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1675', 'dumbbell reverse spider curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con la espalda recta, con una mancuerna en cada mano, las palmas hacia tu cuerpo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1675-6sMAmNv.jpg', 'videos/1675-6sMAmNv.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0385', 'dumbbell reverse wrist curl', 'lower arms', 'lower arms', 'dumbbell', 'Sit on a bench or chair with your feet flat on the ground. Hold a dumbbell in each hand with an overhand grip, palms facing down. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the dumbbells towards your body. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco o silla con los pies apoyados en el suelo. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia abajo. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/0385-BLCvwr2.jpg', 'videos/0385-BLCvwr2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1459', 'dumbbell romanian deadlift', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly. Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que las rodillas se flexionen ligeramente. Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego empuja con los talones y activa los glúteos para volver a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/1459-rR0LJzx.jpg', 'videos/1459-rR0LJzx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0386', 'dumbbell rotation reverse fly', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor. Rotate your arms so that your palms are facing downwards. Slowly lower your arms back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adentro. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Gira los brazos de modo que las palmas queden mirando hacia abajo. Baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/0386-prbWx1D.jpg', 'videos/0386-prbWx1D.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2397', 'dumbbell scott press', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with a dumbbell in each hand, palms facing forward. Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward. Press the dumbbells upward until your arms are fully extended. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'delts', 'images/2397-5vfAI0I.jpg', 'videos/2397-5vfAI0I.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0387', 'dumbbell seated alternate front raise', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides. Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat with the other arm. Alternate between arms for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos extendidos hacia abajo a los lados. Manteniendo los brazos rectos, levanta una mancuerna frente a ti hasta que quede paralela al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', 'trapezius', '["trapezius","biceps"]'::jsonb, 'delts', 'images/0387-gH5fRsC.jpg', 'videos/0387-gH5fRsC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1676', 'dumbbell seated alternate hammer curl on exercise ball', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing your body and your arms fully extended. Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat the movement with the opposite arm. Continue alternating arms for the desired number of repetitions.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos. Manteniendo la parte superior de los brazos fija, exhala y flexiona una mancuerna hacia el hombro mientras mantienes la palma hacia tu cuerpo. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo contrario. Continúa alternando los brazos durante el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1676-QLRmNeT.jpg', 'videos/1676-QLRmNeT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0388', 'dumbbell seated alternate press', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with a dumbbell in each hand, palms facing forward. Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward. Press one dumbbell up overhead, fully extending your arm. Lower the dumbbell back down to shoulder height. Repeat with the other arm. Continue alternating arms for the desired number of repetitions.', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Presiona una mancuerna hacia arriba, por encima de la cabeza, extendiendo completamente el brazo. Baja la mancuerna de vuelta a la altura de los hombros. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'delts', 'images/0388-QT5Q0nK.jpg', 'videos/0388-QT5Q0nK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3546', 'dumbbell seated alternate shoulder', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height. Press one dumbbell up overhead while keeping the other dumbbell at shoulder height. Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead. Continue alternating between arms for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano, con las palmas hacia adentro, y levántalas a la altura de los hombros. Presiona una mancuerna hacia arriba, por encima de la cabeza, mientras mantienes la otra mancuerna a la altura de los hombros. Baja la mancuerna levantada de vuelta a la altura de los hombros mientras presionas simultáneamente la otra mancuerna por encima de la cabeza. Continúa alternando entre los brazos durante el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/3546-q7qkONO.jpg', 'videos/3546-q7qkONO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0389', 'dumbbell seated bench extension', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell with both hands and extend your arms straight up above your head. Slowly lower the dumbbell behind your head, keeping your elbows close to your ears. Pause for a moment, then raise the dumbbell back up to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza. Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas. Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0389-JhYSVwT.jpg', 'videos/0389-JhYSVwT.gif');
